INSERT INTO public.questions (chapter, question_text, options, correct_answer) VALUES
(1, 'Siapakah penulis buku referensi Pramuka "Boyman"?', '["A. Lord Robert Baden Powell","B. Sri Sultan Hamengkubuwono IX","C. Andri Bob Sunardi","D. Soenardjo Atmodipuro"]'::jsonb, 'C. Andri Bob Sunardi'),
(1, 'Sifat kepramukaan yang penyelenggaraannya disesuaikan dengan keadaan dan kebutuhan masyarakat di negaranya adalah sifat...', '["A. Universal","B. Nasional","C. Internasional","D. Fleksibel"]'::jsonb, 'B. Nasional'),
(1, 'Kepramukaan dapat berlaku untuk siapa saja dan diselenggarakan di mana saja. Ini disebut sifat...', '["A. Universal","B. Nasional","C. Internasional","D. Global"]'::jsonb, 'A. Universal'),
(1, 'Kepramukaan harus dapat mengembangkan rasa persaudaraan dan persahabatan antar sesama manusia. Ini adalah cerminan dari sifat...', '["A. Universal","B. Internasional","C. Nasional","D. Kemanusiaan"]'::jsonb, 'B. Internasional'),
(1, 'Fungsi kepramukaan bagi peserta didik (anak/pemuda) pada dasarnya adalah sebagai...', '["A. Kewajiban moral","B. Pekerjaan sosial","C. Permainan yang menarik","D. Pengabdian tanpa batas"]'::jsonb, 'C. Permainan yang menarik'),
(1, 'Bagi orang dewasa, kepramukaan bukan lagi permainan, melainkan suatu tugas yang memerlukan keikhlasan. Ini adalah fungsi sebagai...', '["A. Beban moral","B. Pengabdian","C. Hobi","D. Tanggung jawab negara"]'::jsonb, 'B. Pengabdian'),
(1, 'Kepramukaan berfungsi sebagai alat untuk memenuhi kebutuhan dan tujuan masyarakat. Ini adalah fungsi kepramukaan bagi...', '["A. Peserta Didik","B. Pembina","C. Pelatih","D. Masyarakat dan Organisasi"]'::jsonb, 'D. Masyarakat dan Organisasi'),
(1, 'Proses pendidikan di luar lingkungan sekolah dan keluarga dalam bentuk kegiatan menarik di alam terbuka disebut...', '["A. Pendidikan Jasmani","B. Kepramukaan","C. Pecinta Alam","D. Ekstrakurikuler"]'::jsonb, 'B. Kepramukaan'),
(1, 'Orang-orang atau anggota yang mengikuti kegiatan dan tergabung di dalam organisasi kepanduan di Indonesia disebut...', '["A. Pramuka","B. Pemuda Pancasila","C. Pandu Hidayatullah","D. Relawan"]'::jsonb, 'A. Pramuka'),
(1, 'Organisasi atau wadah resmi yang menyelenggarakan pendidikan kepramukaan di Indonesia adalah...', '["A. Kwartir Nasional","B. WOSM","C. Gerakan Pramuka","D. Departemen Pendidikan"]'::jsonb, 'C. Gerakan Pramuka'),
(1, 'Kepanjangan dari PRAMUKA adalah...', '["A. Praja Muda Karana","B. Pemuda Rakyat Mandiri Utama dan Karya","C. Praja Muda Karya","D. Pandu Rakyat Muda Karana"]'::jsonb, 'A. Praja Muda Karana'),
(1, 'Istilah Praja Muda Karana memiliki arti...', '["A. Pemuda yang berani dan mandiri","B. Rakyat muda yang suka berkarya","C. Jiwa muda yang tangguh","D. Pasukan muda yang siap sedia"]'::jsonb, 'B. Rakyat muda yang suka berkarya'),
(1, 'Bapak Pramuka Indonesia adalah...', '["A. Ir. Soekarno","B. Ki Hajar Dewantara","C. Sri Sultan Hamengkubuwono IX","D. H. Mutahar"]'::jsonb, 'C. Sri Sultan Hamengkubuwono IX'),
(1, 'Bapak Pandu Dunia (Chief Scout of the World) adalah...', '["A. Lord Robert Baden Powell","B. William T. Smyth","C. Lord Edward Cecil","D. Arthur Pearson"]'::jsonb, 'A. Lord Robert Baden Powell'),
(1, 'Tujuan Gerakan Pramuka yang pertama adalah membentuk anggota pramuka agar memiliki kepribadian yang...', '["A. Cerdas dan tangkas","B. Mandiri dan berani","C. Beriman, bertakwa, dan berakhlak mulia","D. Kuat secara fisik"]'::jsonb, 'C. Beriman, bertakwa, dan berakhlak mulia'),
(1, 'Tujuan Gerakan Pramuka yang kedua adalah agar anggota pramuka menjadi warga negara yang...', '["A. Siap tempur","B. Berjiwa Pancasila","C. Pandai berbisnis","D. Patuh pada pimpinan"]'::jsonb, 'B. Berjiwa Pancasila'),
(1, 'Salah satu pilar metode kepramukaan adalah "Learning by Doing", yang artinya...', '["A. Belajar melalui buku","B. Belajar sambil melakukan","C. Belajar dari kesalahan","D. Belajar bersama-sama"]'::jsonb, 'B. Belajar sambil melakukan'),
(1, 'Penggolongan usia Pramuka Siaga adalah...', '["A. 7 - 10 tahun","B. 11 - 15 tahun","C. 16 - 20 tahun","D. 21 - 25 tahun"]'::jsonb, 'A. 7 - 10 tahun'),
(1, 'Penggolongan usia Pramuka Penggalang adalah...', '["A. 7 - 10 tahun","B. 11 - 15 tahun","C. 16 - 20 tahun","D. 21 - 25 tahun"]'::jsonb, 'B. 11 - 15 tahun'),
(1, 'Penggolongan usia Pramuka Penegak adalah...', '["A. 7 - 10 tahun","B. 11 - 15 tahun","C. 16 - 20 tahun","D. 21 - 25 tahun"]'::jsonb, 'C. 16 - 20 tahun'),
(1, 'Penggolongan usia Pramuka Pandega adalah...', '["A. 11 - 15 tahun","B. 16 - 20 tahun","C. 21 - 25 tahun","D. 26 - 30 tahun"]'::jsonb, 'C. 21 - 25 tahun'),
(1, 'Kode Kehormatan bagi Pramuka Siaga terdiri dari...', '["A. Trisatya dan Dasadarma","B. Dwisatya dan Dwidarma","C. Pancasila dan UUD","D. Janji Pandu"]'::jsonb, 'B. Dwisatya dan Dwidarma'),
(1, 'Kode Kehormatan bagi Pramuka Penggalang, Penegak, dan Pandega terdiri dari...', '["A. Dwisatya dan Dwidarma","B. Trisatya dan Dasadarma","C. Catur Darma","D. Sumpah Pemuda"]'::jsonb, 'B. Trisatya dan Dasadarma'),
(1, 'Sistem Pendidikan Kepramukaan menggunakan Sistem Among yang digagas oleh...', '["A. Ir. Soekarno","B. Moh. Hatta","C. Ki Hajar Dewantara","D. Jenderal Sudirman"]'::jsonb, 'C. Ki Hajar Dewantara'),
(1, 'Semboyan Sistem Among di depan memberikan teladan adalah...', '["A. Tut Wuri Handayani","B. Ing Madyo Mangun Karso","C. Ing Ngarso Sung Tulodo","D. Bhinneka Tunggal Ika"]'::jsonb, 'C. Ing Ngarso Sung Tulodo'),
(1, 'Semboyan Sistem Among di tengah membangun kemauan adalah...', '["A. Ing Ngarso Sung Tulodo","B. Ing Madyo Mangun Karso","C. Tut Wuri Handayani","D. Rawe-rawe rantas"]'::jsonb, 'B. Ing Madyo Mangun Karso'),
(1, 'Semboyan Sistem Among di belakang memberikan dorongan adalah...', '["A. Ing Madyo Mangun Karso","B. Ing Ngarso Sung Tulodo","C. Tut Wuri Handayani","D. Jer Basuki Mawa Beya"]'::jsonb, 'C. Tut Wuri Handayani'),
(1, 'Satuan terkecil dalam Pramuka Siaga disebut...', '["A. Barung","B. Regu","C. Sangga","D. Reka"]'::jsonb, 'A. Barung'),
(1, 'Satuan terkecil dalam Pramuka Penggalang disebut...', '["A. Barung","B. Regu","C. Sangga","D. Reka"]'::jsonb, 'B. Regu'),
(1, 'Satuan terkecil dalam Pramuka Penegak disebut...', '["A. Barung","B. Regu","C. Sangga","D. Reka"]'::jsonb, 'C. Sangga'),
(1, 'Satuan terkecil dalam Pramuka Pandega disebut...', '["A. Barung","B. Regu","C. Sangga","D. Reka"]'::jsonb, 'D. Reka'),
(1, 'Kumpulan dari beberapa Barung dalam Siaga disebut...', '["A. Perindukan","B. Pasukan","C. Ambalan","D. Racana"]'::jsonb, 'A. Perindukan'),
(1, 'Kumpulan dari beberapa Regu dalam Penggalang disebut...', '["A. Perindukan","B. Pasukan","C. Ambalan","D. Racana"]'::jsonb, 'B. Pasukan'),
(1, 'Kumpulan dari beberapa Sangga dalam Penegak disebut...', '["A. Perindukan","B. Pasukan","C. Ambalan","D. Racana"]'::jsonb, 'C. Ambalan'),
(1, 'Wadah pembinaan Pramuka Pandega di Perguruan Tinggi disebut...', '["A. Perindukan","B. Pasukan","C. Ambalan","D. Racana"]'::jsonb, 'D. Racana'),
(1, 'Tanda kecakapan dalam kepramukaan dibagi menjadi dua, yaitu...', '["A. Siaga dan Penggalang","B. TKU dan TKK","C. Bantara dan Laksana","D. Mayor dan Minor"]'::jsonb, 'B. TKU dan TKK'),
(1, 'TKU singkatan dari...', '["A. Tanda Kehormatan Umum","B. Tanda Kelulusan Ujian","C. Tanda Kecakapan Umum","D. Tanda Kemahiran Utama"]'::jsonb, 'C. Tanda Kecakapan Umum'),
(1, 'TKK singkatan dari...', '["A. Tanda Kecakapan Khusus","B. Tanda Kehormatan Khusus","C. Tanda Kemahiran Khusus","D. Tanda Kepemimpinan Kelompok"]'::jsonb, 'A. Tanda Kecakapan Khusus'),
(1, 'Tingkatan TKU pada Pramuka Siaga adalah...', '["A. Mula, Bantu, Tata","B. Ramu, Rakit, Terap","C. Bantara, Laksana","D. Purwa, Madya, Utama"]'::jsonb, 'A. Mula, Bantu, Tata'),
(1, 'Tingkatan TKU pada Pramuka Penggalang adalah...', '["A. Mula, Bantu, Tata","B. Ramu, Rakit, Terap","C. Bantara, Laksana","D. Purwa, Madya, Utama"]'::jsonb, 'B. Ramu, Rakit, Terap'),
(1, 'Tingkatan TKU pada Pramuka Penegak adalah...', '["A. Mula, Bantu, Tata","B. Ramu, Rakit, Terap","C. Bantara, Laksana","D. Pandega"]'::jsonb, 'C. Bantara, Laksana'),
(1, 'Tingkatan TKK (Tanda Kecakapan Khusus) dibagi menjadi 3 tingkatan, yaitu...', '["A. Mula, Bantu, Tata","B. Ramu, Rakit, Terap","C. Purwa, Madya, Utama","D. Bawah, Menengah, Atas"]'::jsonb, 'C. Purwa, Madya, Utama'),
(1, 'Lambang Gerakan Pramuka Indonesia adalah...', '["A. Bunga Lily","B. Tunas Kelapa","C. Burung Garuda","D. Padi dan Kapas"]'::jsonb, 'B. Tunas Kelapa'),
(1, 'Pencipta lambang Tunas Kelapa adalah...', '["A. H. Mutahar","B. W.R. Supratman","C. Soenardjo Atmodipuro","D. Sri Sultan HB IX"]'::jsonb, 'C. Soenardjo Atmodipuro'),
(1, 'Bentuk lambang Pramuka Internasional (WOSM) adalah...', '["A. Tunas Kelapa","B. Bunga Lily (Fleur-de-lis)","C. Bintang Segi Lima","D. Burung Elang"]'::jsonb, 'B. Bunga Lily (Fleur-de-lis)'),
(1, 'Gerakan Pramuka resmi diperkenalkan kepada rakyat Indonesia pada tanggal...', '["A. 14 Agustus 1961","B. 17 Agustus 1945","C. 28 Oktober 1928","D. 20 Mei 1908"]'::jsonb, 'A. 14 Agustus 1961'),
(1, 'Oleh karena itu, Hari Pramuka di Indonesia diperingati setiap tanggal...', '["A. 17 Agustus","B. 1 Juni","C. 14 Agustus","D. 28 Oktober"]'::jsonb, 'C. 14 Agustus'),
(1, 'Undang-Undang yang mengatur tentang Gerakan Pramuka saat ini adalah...', '["A. UU No. 20 Tahun 2003","B. UU No. 12 Tahun 2010","C. UU No. 14 Tahun 2005","D. UU No. 40 Tahun 2009"]'::jsonb, 'B. UU No. 12 Tahun 2010'),
(1, 'Motto Gerakan Pramuka adalah...', '["A. Bersatu Kita Teguh","B. Satyaku Kudarmakan, Darmaku Kubaktikan","C. Ikhlas Bakti Bina Bangsa","D. Rawe-rawe rantas"]'::jsonb, 'B. Satyaku Kudarmakan, Darmaku Kubaktikan'),
(1, 'Tingkatan tertinggi dalam setiap golongan Pramuka yang telah memenuhi syarat pencapaian Garuda disebut...', '["A. Pramuka Utama","B. Pramuka Teladan","C. Pramuka Garuda","D. Pramuka Bintang"]'::jsonb, 'C. Pramuka Garuda'),
(3, 'Nama lengkap Bapak Pandu Dunia adalah...', '["A. Robert Stephenson Smyth Baden-Powell","B. William Stephenson Baden-Powell","C. Arthur Smyth Baden-Powell","D. George Stephenson Baden-Powell"]'::jsonb, 'A. Robert Stephenson Smyth Baden-Powell'),
(3, 'Baden-Powell lahir di kota...', '["A. Manchester","B. Liverpool","C. London","D. Birmingham"]'::jsonb, 'C. London'),
(3, 'Tanggal lahir Baden-Powell adalah...', '["A. 22 Februari 1857","B. 22 Februari 1858","C. 14 Agustus 1857","D. 20 Mei 1857"]'::jsonb, 'A. 22 Februari 1857'),
(3, 'Nama ayah Baden-Powell adalah...', '["A. Prof. William T. Smyth","B. Prof. Domine Baden-Powell","C. Lord Edward Cecil","D. Dr. Haig Brown"]'::jsonb, 'B. Prof. Domine Baden-Powell'),
(3, 'Profesi ayah Baden-Powell adalah seorang...', '["A. Dokter Bedah Kerajaan","B. Laksamana Angkatan Laut","C. Guru Besar Geometri di Universitas Oxford","D. Jenderal Kavaleri"]'::jsonb, 'C. Guru Besar Geometri di Universitas Oxford'),
(3, 'Nama ibu dari Baden-Powell adalah...', '["A. Miss Henrietta Grace Smyth","B. Olave St. Clair Soames","C. Agnes Baden-Powell","D. Rose Smyth"]'::jsonb, 'A. Miss Henrietta Grace Smyth'),
(3, 'Ayah dari ibu Baden-Powell (kakek dari pihak ibu) adalah seorang laksamana bernama...', '["A. Admiral Horatio Nelson","B. Admiral William T. Smyth","C. Admiral John Jervis","D. Admiral Francis Drake"]'::jsonb, 'B. Admiral William T. Smyth'),
(3, 'Ayah Baden-Powell meninggal dunia ketika Baden-Powell berusia...', '["A. 3 tahun","B. 5 tahun","C. 7 tahun","D. 10 tahun"]'::jsonb, 'A. 3 tahun'),
(3, 'Julukan Baden-Powell saat bersekolah di Charterhouse School karena kebiasaannya mandi air dingin adalah...', '["A. Ice Boy","B. Bathing Towel","C. Water Polo","D. Cold Bear"]'::jsonb, 'B. Bathing Towel'),
(3, 'Kepala sekolah di Charterhouse yang sangat berpengaruh terhadap pembentukan karakter Baden-Powell adalah...', '["A. Dr. William Smyth","B. Dr. Haig Brown","C. Prof. Domine","D. Lord Cecil"]'::jsonb, 'B. Dr. Haig Brown'),
(3, 'Setelah lulus dari Charterhouse, Baden-Powell mengikuti ujian militer dan lulus kavaleri dengan urutan ke...', '["A. Satu","B. Dua","C. Tiga","D. Empat"]'::jsonb, 'B. Dua'),
(3, 'Pasukan kavaleri yang pertama kali ditempati Baden-Powell di India adalah...', '["A. 5th Royal","B. 1st Infantry","C. 13th Hussars","D. 2nd Dragoons"]'::jsonb, 'C. 13th Hussars'),
(3, 'Baden-Powell pertama kali ditugaskan ke India sebagai prajurit muda pada tahun...', '["A. 1876","B. 1886","C. 1896","D. 1906"]'::jsonb, 'A. 1876'),
(3, 'Pangkat pertama Baden-Powell saat bergabung di ketentaraan di India adalah...', '["A. Letnan Kolonel","B. Kapten","C. Pembantu Letnan (Sub-Lieutenant)","D. Jenderal"]'::jsonb, 'C. Pembantu Letnan (Sub-Lieutenant)'),
(3, 'Suku Zulu, Ashanti, dan Matabele di Afrika memberikan julukan khusus kepada Baden-Powell, yaitu...', '["A. Singa Hitam","B. Elang Perkasa","C. Impeesa","D. Bintang Gurun"]'::jsonb, 'C. Impeesa'),
(3, 'Arti dari julukan "Impeesa" yang diberikan oleh suku di Afrika adalah...', '["A. Singa yang perkasa","B. Burung elang yang bermata tajam","C. Serigala yang tidak pernah tidur","D. Ksatria putih"]'::jsonb, 'C. Serigala yang tidak pernah tidur'),
(3, 'Baden-Powell berhasil mempertahankan sebuah kota dari kepungan bangsa Boer di Afrika Selatan selama 217 hari. Kota tersebut bernama...', '["A. Pretoria","B. Mafeking","C. Johannesburg","D. Cape Town"]'::jsonb, 'B. Mafeking'),
(3, 'Peristiwa pengepungan kota Mafeking terjadi pada tahun...', '["A. 1899 - 1900","B. 1907 - 1908","C. 1914 - 1918","D. 1888 - 1889"]'::jsonb, 'A. 1899 - 1900'),
(3, 'Buku panduan pelacakan militer yang ditulis Baden-Powell dan kelak disukai oleh anak-anak muda Inggris adalah...', '["A. Scouting for Boys","B. Aids to Scouting","C. Rovering to Success","D. The Jungle Book"]'::jsonb, 'B. Aids to Scouting'),
(3, 'Buku "Aids to Scouting" diterbitkan pada tahun...', '["A. 1899","B. 1908","C. 1912","D. 1920"]'::jsonb, 'A. 1899'),
(3, 'Perkemahan percobaan kepanduan pertama kali diadakan oleh Baden-Powell di sebuah pulau bernama...', '["A. Pulau Gilwell","B. Pulau Brownsea","C. Pulau Wight","D. Pulau Corsica"]'::jsonb, 'B. Pulau Brownsea'),
(3, 'Perkemahan di Pulau Brownsea yang menjadi tonggak sejarah kepramukaan dilaksanakan pada tahun...', '["A. 1899","B. 1907","C. 1912","D. 1920"]'::jsonb, 'B. 1907'),
(3, 'Berapa jumlah anak laki-laki yang mengikuti perkemahan percobaan di Pulau Brownsea?', '["A. 15 anak","B. 22 anak","C. 30 anak","D. 40 anak"]'::jsonb, 'B. 22 anak'),
(3, 'Teman tentara yang membantu Baden-Powell mengurus perkemahan di Pulau Brownsea adalah...', '["A. Mayor Kenneth McLaren","B. Lord Edward Cecil","C. William Smyth","D. Jenderal Kitchener"]'::jsonb, 'A. Mayor Kenneth McLaren'),
(3, 'Buku panduan utama yang menjadi cikal bakal berdirinya gerakan kepanduan dunia adalah...', '["A. Aids to Scouting","B. Scouting for Boys","C. Rovering to Success","D. The Wolf Cub Handbook"]'::jsonb, 'B. Scouting for Boys'),
(3, 'Buku "Scouting for Boys" karya Baden-Powell pertama kali diterbitkan pada tahun...', '["A. 1907","B. 1908","C. 1910","D. 1912"]'::jsonb, 'B. 1908'),
(3, 'Organisasi kepanduan putri (Girl Guides) pertama kali dibentuk dengan bantuan adik perempuan Baden-Powell yang bernama...', '["A. Olave St. Clair Soames","B. Henrietta Grace","C. Agnes Baden-Powell","D. Rose Powell"]'::jsonb, 'C. Agnes Baden-Powell'),
(3, 'Organisasi Girl Guides (Kepanduan Putri) dirintis pada tahun...', '["A. 1908","B. 1910","C. 1912","D. 1920"]'::jsonb, 'B. 1910'),
(3, 'Kepanduan untuk golongan anak-anak (Siaga/Wolf Cub) didirikan oleh Baden-Powell pada tahun...', '["A. 1910","B. 1916","C. 1920","D. 1922"]'::jsonb, 'B. 1916'),
(3, 'Buku panduan yang digunakan Baden-Powell untuk menginspirasi golongan Siaga (Wolf Cub) adalah...', '["A. The Jungle Book","B. Tarzan of the Apes","C. Peter Pan","D. Treasure Island"]'::jsonb, 'A. The Jungle Book'),
(3, 'Penulis buku "The Jungle Book" yang menginspirasi pembentukan golongan Siaga adalah...', '["A. J.K. Rowling","B. Arthur Conan Doyle","C. Rudyard Kipling","D. Mark Twain"]'::jsonb, 'C. Rudyard Kipling'),
(3, 'Kepanduan untuk golongan pemuda (Penegak/Rover Scout) dibentuk pada tahun...', '["A. 1916","B. 1918","C. 1920","D. 1922"]'::jsonb, 'B. 1918'),
(3, 'Buku panduan untuk Rover Scout yang ditulis oleh Baden-Powell pada tahun 1922 berjudul...', '["A. Scouting for Boys","B. Aids to Scouting","C. Rovering to Success","D. Wolf Cub Handbook"]'::jsonb, 'C. Rovering to Success'),
(3, 'Jambore Kepanduan Dunia pertama kali diadakan di gedung...', '["A. Crystal Palace","B. Olympia Hall","C. Wembley Stadium","D. Royal Albert Hall"]'::jsonb, 'B. Olympia Hall'),
(3, 'Jambore Dunia pertama diadakan di kota London pada tahun...', '["A. 1918","B. 1920","C. 1922","D. 1924"]'::jsonb, 'B. 1920'),
(3, 'Pada malam terakhir Jambore Dunia pertama, Baden-Powell secara resmi diangkat menjadi...', '["A. Perdana Menteri Inggris","B. Jenderal Kehormatan","C. Bapak Pandu Dunia (Chief Scout of the World)","D. Lord of Gilwell"]'::jsonb, 'C. Bapak Pandu Dunia (Chief Scout of the World)'),
(3, 'Gelar kehormatan "Lord" (Baron) dianugerahkan kepada Baden-Powell oleh Raja George V pada tahun...', '["A. 1920","B. 1929","C. 1937","D. 1941"]'::jsonb, 'B. 1929'),
(3, 'Nama istri Baden-Powell yang kelak menjadi Chief Guide of the World adalah...', '["A. Agnes Baden-Powell","B. Henrietta Grace","C. Olave St. Clair Soames","D. Lady Diana"]'::jsonb, 'C. Olave St. Clair Soames'),
(3, 'Baden-Powell pensiun dari dinas kemiliteran Inggris dengan pangkat terakhir...', '["A. Letnan Jenderal","B. Mayor Jenderal","C. Kolonel","D. Marsekal"]'::jsonb, 'A. Letnan Jenderal'),
(3, 'Raja Inggris yang menyarankan Baden-Powell untuk pensiun dari militer agar bisa membesarkan Gerakan Kepanduan adalah...', '["A. Raja George V","B. Raja Edward VII","C. Ratu Victoria","D. Raja George VI"]'::jsonb, 'B. Raja Edward VII'),
(3, 'Pada tahun 1919, W. de Bois Maclaren menyumbangkan sebidang tanah untuk pusat pelatihan pembina pramuka yang diberi nama...', '["A. Brownsea Island","B. Gilwell Park","C. Olympia Hall","D. Mafeking Camp"]'::jsonb, 'B. Gilwell Park'),
(3, 'Kursus Pembina Pramuka (Wood Badge) pertama kali diselenggarakan di Gilwell Park pada tahun...', '["A. 1907","B. 1910","C. 1919","D. 1920"]'::jsonb, 'C. 1919'),
(3, 'Kalung manik-manik kayu (Wood Badge) berasal dari kalung pimpinan suku Afrika yang pernah dikalahkan oleh Baden-Powell, bernama...', '["A. Zulu","B. Ashanti","C. Dinizulu","D. Matabele"]'::jsonb, 'C. Dinizulu'),
(3, 'Simbol dari pusat pelatihan pembina Gilwell Park adalah...', '["A. Tunas Kelapa","B. Kapak menancap di balok kayu","C. Bunga Lily Emas","D. Api Unggun"]'::jsonb, 'B. Kapak menancap di balok kayu'),
(3, 'Baden-Powell menghabiskan masa tuanya dan meninggal dunia di negara...', '["A. Inggris","B. Afrika Selatan","C. Kenya","D. India"]'::jsonb, 'C. Kenya'),
(3, 'Baden-Powell meninggal dunia pada tanggal...', '["A. 8 Januari 1941","B. 22 Februari 1941","C. 14 Agustus 1941","D. 17 Agustus 1941"]'::jsonb, 'A. 8 Januari 1941'),
(3, 'Baden-Powell dimakamkan di pemakaman St. Peter, di kota...', '["A. London","B. Mafeking","C. Nyeri","D. Nairobi"]'::jsonb, 'C. Nyeri'),
(3, 'Usia Baden-Powell saat meninggal dunia adalah...', '["A. 73 tahun","B. 83 tahun","C. 93 tahun","D. 63 tahun"]'::jsonb, 'B. 83 tahun'),
(3, 'Pada batu nisan makam Baden-Powell terdapat tanda jejak kepanduan berupa lingkaran dengan titik di tengah yang memiliki arti...', '["A. Bahaya di depan","B. Saya telah pulang","C. Jalan terus","D. Ada air bersih"]'::jsonb, 'B. Saya telah pulang'),
(3, 'Organisasi kepanduan dunia saat ini bernaung di bawah organisasi bernama WOSM, singkatan dari...', '["A. World Organization of the Scout Movement","B. World Office of Scout Management","C. Worldwide Organization of Scout Member","D. World Order of Scout Movement"]'::jsonb, 'A. World Organization of the Scout Movement'),
(5, 'Bab 5 dalam buku referensi Boyman secara khusus membahas rangkuman dari buku legendaris karya Baden-Powell yang berjudul...', '["A. Aids to Scouting","B. Scouting for Boys","C. Rovering to Success","D. The Jungle Book"]'::jsonb, 'B. Scouting for Boys'),
(5, 'Buku Scouting for Boys pada dasarnya dibagi ke dalam beberapa sub-bab yang disebut dengan istilah...', '["A. Kisah Rimba","B. Panduan Bertahan Hidup","C. Cerita Api Unggun","D. Jejak Petualang"]'::jsonb, 'C. Cerita Api Unggun'),
(5, 'Ada berapa total Cerita Api Unggun (Campfire Yarns) yang menjadi susunan utama materi Scouting for Boys?', '["A. 10 Cerita","B. 15 Cerita","C. 20 Cerita","D. 26 Cerita"]'::jsonb, 'D. 26 Cerita'),
(5, 'Cerita Api Unggun ke-1 membahas sejarah tentang pasukan anak laki-laki di Afrika yang menjadi inspirasi kepanduan, yang disebut...', '["A. Boys Brigade","B. Mafeking Cadet Corps","C. Zulu Warriors","D. Brownsea Scouts"]'::jsonb, 'B. Mafeking Cadet Corps'),
(5, 'Pemimpin pasukan anak-anak pada masa pengepungan Mafeking tersebut adalah...', '["A. Lord Edward Cecil","B. Mayor Kenneth McLaren","C. Jenderal Kitchener","D. William T. Smyth"]'::jsonb, 'A. Lord Edward Cecil'),
(5, 'Baden-Powell menyadari kehebatan pasukan anak-anak di Mafeking yang kemudian menjadi cikal bakal pentingnya peran kaum muda. Pengepungan kota Mafeking terjadi di negara...', '["A. Inggris","B. India","C. Afrika Selatan","D. Kenya"]'::jsonb, 'C. Afrika Selatan'),
(5, 'Cerita Api Unggun ke-4 membahas inti dari sistem kepramukaan yang membagi anggota ke dalam kelompok kecil, disebut dengan...', '["A. Sistem Regu (Patrol System)","B. Sistem Pasukan","C. Sistem Komando","D. Sistem Kelompok"]'::jsonb, 'A. Sistem Regu (Patrol System)'),
(5, 'Menurut gagasan awal Baden-Powell, jumlah anggota yang ideal dalam satu regu pramuka (patrol) adalah...', '["A. 2 sampai 4 orang","B. 4 sampai 6 orang","C. 6 sampai 8 orang","D. 10 sampai 12 orang"]'::jsonb, 'C. 6 sampai 8 orang'),
(5, 'Sebutan untuk pemimpin regu dalam bahasa Inggris yang dicetuskan oleh Baden-Powell adalah...', '["A. Squad Leader","B. Patrol Leader","C. Scout Master","D. Team Captain"]'::jsonb, 'B. Patrol Leader'),
(5, 'Cerita Api Unggun ke-8 membahas tentang keterampilan membuat bangunan darurat menggunakan kayu dan tali, yang dalam istilah kepramukaan disebut...', '["A. Navigasi","B. Pionering / Kepeloporan","C. Survival","D. Menaksir"]'::jsonb, 'B. Pionering / Kepeloporan'),
(5, 'Simpul dasar dalam pionering yang berguna untuk menyambung dua utas tali yang sama besar dan tidak licin adalah...', '["A. Simpul Anyam (Sheet Bend)","B. Simpul Mati (Reef Knot)","C. Simpul Tiang (Bowline)","D. Simpul Pangkal (Clove Hitch)"]'::jsonb, 'B. Simpul Mati (Reef Knot)'),
(5, 'Simpul yang berguna untuk mengikat leher binatang agar tidak tercekik, serta sering menjadi simpul dasar penyelamatan adalah...', '["A. Simpul Anyam (Sheet Bend)","B. Simpul Mati (Reef Knot)","C. Simpul Tiang (Bowline)","D. Simpul Pangkal (Clove Hitch)"]'::jsonb, 'C. Simpul Tiang (Bowline)'),
(5, 'Simpul yang paling sering digunakan untuk memulai dan mengakhiri sebuah ikatan pada tongkat pionering adalah...', '["A. Simpul Anyam (Sheet Bend)","B. Simpul Mati (Reef Knot)","C. Simpul Tiang (Bowline)","D. Simpul Pangkal (Clove Hitch)"]'::jsonb, 'D. Simpul Pangkal (Clove Hitch)'),
(5, 'Simpul yang digunakan untuk menyambung dua utas tali yang ukurannya tidak sama besar dan dalam keadaan kering adalah...', '["A. Simpul Anyam (Sheet Bend)","B. Simpul Mati (Reef Knot)","C. Simpul Tiang (Bowline)","D. Simpul Pangkal (Clove Hitch)"]'::jsonb, 'A. Simpul Anyam (Sheet Bend)'),
(5, 'Ikatan yang digunakan untuk menggabungkan dua buah tongkat yang bersilangan tegak lurus (membentuk sudut 90 derajat) adalah...', '["A. Ikatan Silang (Diagonal Lashing)","B. Ikatan Palang (Square Lashing)","C. Ikatan Kaki Tiga (Tripod Lashing)","D. Ikatan Canggah"]'::jsonb, 'B. Ikatan Palang (Square Lashing)'),
(5, 'Cerita Api Unggun ke-9 membahas mengenai kehidupan di alam terbuka, yaitu rutinitas...', '["A. Penjelajahan","B. Perkemahan (Camping)","C. Pertolongan Pertama","D. Pengamatan Jejak"]'::jsonb, 'B. Perkemahan (Camping)'),
(5, 'Hal yang paling utama dan penting untuk diperhatikan saat memilih lokasi untuk mendirikan tenda perkemahan adalah...', '["A. Pemandangan yang indah","B. Dekat sumber air bersih dan aman dari bahaya alam","C. Banyak pepohonan rindang","D. Dekat dengan jalan raya"]'::jsonb, 'B. Dekat sumber air bersih dan aman dari bahaya alam'),
(5, 'Cerita Api Unggun ke-10 memberikan panduan teknis yang sangat dibutuhkan regu mandiri, yaitu tentang...', '["A. Masakan di Perkemahan (Camp Cooking)","B. Tanda Jejak (Tracking)","C. Peta dan Kompas","D. Pertolongan Pertama"]'::jsonb, 'A. Masakan di Perkemahan (Camp Cooking)'),
(5, 'Salah satu makanan khas perkemahan ala Baden-Powell, di mana adonan tepung dililitkan pada sebatang kayu lalu dipanggang di atas bara api, disebut...', '["A. Pancake","B. Roti Lilit (Twist)","C. Barbeque","D. Biskuit Keras (Hardtack)"]'::jsonb, 'B. Roti Lilit (Twist)'),
(5, 'Cerita Api Unggun ke-11 dan 12 mengajarkan keterampilan mengasah kepekaan mata di alam terbuka, berupa...', '["A. Mencari dan Mengikuti Jejak (Tracking)","B. Membaca Arah Angin","C. Mengukur Tinggi Pohon","D. Mengenali Jenis Burung"]'::jsonb, 'A. Mencari dan Mengikuti Jejak (Tracking)'),
(5, 'Saat sedang mengikuti jejak di alam bebas, seorang Pramuka dianjurkan untuk berjalan dengan cara...', '["A. Cepat dan terburu-buru","B. Berlari agar segera sampai","C. Tenang sambil memperhatikan keadaan tanah dan sekelilingnya","D. Sambil berteriak agar tidak tersesat"]'::jsonb, 'C. Tenang sambil memperhatikan keadaan tanah dan sekelilingnya'),
(5, 'Dalam sandi jejak Pramuka, susunan batu yang ditumpuk menjadi tiga bagian dan ditambahkan satu batu kecil di sebelah kanan memiliki arti...', '["A. Jalan ke arah kanan","B. Jalan ke arah kiri","C. Bahaya di depan","D. Ada air bersih"]'::jsonb, 'A. Jalan ke arah kanan'),
(5, 'Sebuah lingkaran yang digambar di tanah dengan titik di tengahnya merupakan tanda jejak kepanduan yang berarti...', '["A. Bahaya di depan","B. Saya telah pulang / Kembali ke perkemahan","C. Jalan terus","D. Ada air bersih"]'::jsonb, 'B. Saya telah pulang / Kembali ke perkemahan'),
(5, 'Cerita Api Unggun ke-13 menuntut seorang pandu untuk memiliki kemampuan observasi dan deduksi. Tokoh detektif fiksi yang sering dijadikan contoh oleh Baden-Powell untuk hal ini adalah...', '["A. Hercule Poirot","B. Sherlock Holmes","C. James Bond","D. Inspector Clouseau"]'::jsonb, 'B. Sherlock Holmes'),
(5, 'Cerita Api Unggun ke-14 berjudul "Menyembunyikan Diri - Mengendap" (Stalking). Mengendap sangat berguna di alam bebas untuk...', '["A. Menakut-nakuti teman","B. Menghindari tugas piket","C. Mendekati dan mengamati hewan liar tanpa disadari oleh hewan tersebut","D. Bersembunyi dari pembina"]'::jsonb, 'C. Mendekati dan mengamati hewan liar tanpa disadari oleh hewan tersebut'),
(5, 'Aturan utama yang harus diperhatikan seorang Pramuka saat sedang mengendap mendekati target di alam liar adalah...', '["A. Memakai baju berwarna terang","B. Bergerak berlawanan arah dengan hembusan angin","C. Membunyikan peluit","D. Berjalan dengan langkah berat"]'::jsonb, 'B. Bergerak berlawanan arah dengan hembusan angin'),
(5, 'Cerita Api Unggun ke-15 dan 16 membahas apresiasi terhadap lingkungan hidup, yakni tentang pengetahuan...', '["A. Cuaca dan Iklim","B. Batuan dan Mineral","C. Binatang dan Tumbuh-tumbuhan","D. Sungai dan Laut"]'::jsonb, 'C. Binatang dan Tumbuh-tumbuhan'),
(5, 'Prinsip konservasi dalam kepanduan menyatakan bahwa seorang Pramuka dilarang keras membunuh binatang apa pun, KECUALI...', '["A. Untuk koleksi spesimen","B. Saat perlombaan berburu","C. Ketika terancam bahaya atau terpaksa untuk bertahan hidup/makan","D. Binatang tersebut memiliki bentuk jelek"]'::jsonb, 'C. Ketika terancam bahaya atau terpaksa untuk bertahan hidup/makan'),
(5, 'Pengetahuan seorang Pramuka dalam mengenali berbagai jenis pohon liar, dedaunan, dan akar yang bisa dimakan sangat menunjang kemampuannya dalam bidang...', '["A. Pioneering","B. P3K","C. Survival (Bertahan Hidup)","D. Navigasi Darat"]'::jsonb, 'C. Survival (Bertahan Hidup)'),
(5, 'Cerita Api Unggun ke-17 berjudul "Bagaimana Supaya Kuat", yang memberikan instruksi agar kaum muda terbiasa menjaga...', '["A. Kesehatan fisik dan kebugaran tubuh","B. Kebersihan pakaian","C. Kekuatan senjata","D. Kelancaran berbicara"]'::jsonb, 'A. Kesehatan fisik dan kebugaran tubuh'),
(5, 'Untuk melatih kebugaran tubuh setiap hari, Baden-Powell menyarankan rutinitas senam pagi yang dikenal sebagai...', '["A. Senam Kesegaran Jasmani (SKJ)","B. 6 Latihan Fisik BP (BP Exercises)","C. Senam Aerobik","D. Latihan Angkat Beban"]'::jsonb, 'B. 6 Latihan Fisik BP (BP Exercises)'),
(5, 'Cerita Api Unggun ke-18 dan 19 mengulas tentang kebiasaan yang menyehatkan serta pencegahan penyakit. Baden-Powell sangat mewajibkan pandu bernapas dengan benar melalui...', '["A. Mulut","B. Hidung, bukan mulut","C. Dada","D. Perut"]'::jsonb, 'B. Hidung, bukan mulut'),
(5, 'Penyakit yang sering menyerang anggota perkemahan akibat meminum air mentah atau lingkungan perkemahan yang kurang bersih (sanitasi buruk) adalah...', '["A. Diare dan Disentri","B. Malaria dan Demam Berdarah","C. Flu dan Batuk","D. Asma dan Bronkitis"]'::jsonb, 'A. Diare dan Disentri'),
(5, 'Cerita Api Unggun ke-20 bertemakan "Sikap Kesatria" (Chivalry). Inspirasi utama Baden-Powell dalam membentuk karakter Pramuka ini berasal dari legenda pahlawan kuno, yaitu...', '["A. Gladiator Romawi","B. Samurai Jepang","C. Kesatria Meja Bundar (Knights of the Round Table)","D. Pasukan Sparta"]'::jsonb, 'C. Kesatria Meja Bundar (Knights of the Round Table)'),
(5, 'Raja legendaris Inggris yang memimpin para kesatria mulia dalam perumpamaan Baden-Powell tersebut adalah...', '["A. Raja Richard","B. Raja Henry","C. Raja Arthur","D. Raja Edward"]'::jsonb, 'C. Raja Arthur'),
(5, 'Tokoh orang suci pelindung Inggris (Patron Saint) yang juga dijadikan sebagai pelindung simbolis kaum pandu di seluruh dunia karena keberaniannya membunuh naga adalah...', '["A. Santo Petrus","B. Santo George (St. George)","C. Santo Paulus","D. Santo Yohanes"]'::jsonb, 'B. Santo George (St. George)'),
(5, 'Hari peringatan St. George, yang sering dirayakan secara internasional oleh anggota Pramuka sebagai ajang pembaruan Janji Pramuka, jatuh pada tanggal...', '["A. 14 Agustus","B. 22 Februari","C. 23 April","D. 1 Agustus"]'::jsonb, 'C. 23 April'),
(5, 'Cerita Api Unggun ke-21 menekankan pada konsep utama watak yang membuat seorang pandu dihormati, yaitu...', '["A. Kekayaan","B. Ketampanan","C. Disiplin","D. Kepintaran Akademik"]'::jsonb, 'C. Disiplin'),
(5, 'Ciri sejati dari kedisiplinan seorang Pramuka saat menerima instruksi dari pimpinannya adalah...', '["A. Berdebat terlebih dahulu","B. Menolak jika merasa tidak cocok","C. Mematuhi perintah dan aturan dengan sigap tanpa mengeluh","D. Meminta bayaran"]'::jsonb, 'C. Mematuhi perintah dan aturan dengan sigap tanpa mengeluh'),
(5, 'Cerita Api Unggun ke-22 berjudul "Memperbaiki Diri". Hal ini mengajarkan filosofi bahwa seorang pandu sejati harus...', '["A. Terus mengasah keahlian dan akhlaknya secara mandiri agar hidupnya lebih berguna","B. Selalu meminta bantuan orang lain","C. Menunggu perintah atasan baru bergerak","D. Merasa puas dengan apa yang sudah dicapai"]'::jsonb, 'A. Terus mengasah keahlian dan akhlaknya secara mandiri agar hidupnya lebih berguna'),
(5, 'Cerita Api Unggun ke-23 dan 24 membahas tentang keterampilan vital yang harus dimiliki setiap Pramuka jika terjadi insiden darurat, yakni tentang...', '["A. Menyelamatkan Hidup dan Penanganan Kecelakaan (P3K)","B. Bertahan Hidup di Hutan Belantara (Survival)","C. Navigasi Darat dan Membaca Peta","D. Mengirim Pesan Rahasia"]'::jsonb, 'A. Menyelamatkan Hidup dan Penanganan Kecelakaan (P3K)'),
(5, 'Kaidah terpenting dan pertama kali yang harus dikuasai secara mental saat seorang Pramuka menghadapi situasi kecelakaan parah adalah...', '["A. Langsung memindahkan korban","B. Berteriak sekeras mungkin","C. Tetap tenang dan tidak panik","D. Menutup mata agar tidak takut"]'::jsonb, 'C. Tetap tenang dan tidak panik'),
(5, 'Apabila menemui korban yang mengalami pendarahan hebat (luka terbuka memancar), tindakan Pertolongan Pertama yang paling efektif dilakukan adalah...', '["A. Memberi minum air putih","B. Mengoleskan obat merah","C. Melakukan tekanan langsung pada area luka / balut tekan","D. Membasuh luka dengan air sungai"]'::jsonb, 'C. Melakukan tekanan langsung pada area luka / balut tekan'),
(5, 'Jika pakaian yang dikenakan oleh seseorang tiba-tiba tersambar api dan terbakar, tindakan penyelematan yang paling tepat diinstruksikan oleh Pramuka adalah...', '["A. Menyuruhnya berlari kencang","B. Menyiramnya dengan bensin","C. Menyuruhnya berguling-guling di tanah atau membungkusnya rapat dengan selimut tebal","D. Mengipas-ngipas api agar mati"]'::jsonb, 'C. Menyuruhnya berguling-guling di tanah atau membungkusnya rapat dengan selimut tebal'),
(5, 'Cerita Api Unggun ke-25 mengingatkan tentang tujuan mulia kehadiran gerakan Pramuka dalam masyarakat, yaitu kewajiban untuk...', '["A. Mencari uang sebanyak-banyaknya","B. Menjadi penguasa wilayah","C. Menolong orang lain di setiap kesempatan","D. Menjauhi kehidupan sosial"]'::jsonb, 'C. Menolong orang lain di setiap kesempatan'),
(5, 'Sebuah tradisi pandu yang diajarkan oleh Baden-Powell untuk melakukan setidaknya satu kebaikan kecil setiap harinya tanpa mengharap imbalan disebut dengan istilah...', '["A. Daily Task","B. Scout Promise","C. Good Turn (Berbuat Kebaikan)","D. Boy Scout Law"]'::jsonb, 'C. Good Turn (Berbuat Kebaikan)'),
(5, 'Cerita Api Unggun ke-26, yang menjadi bab pamungkas dalam materi buku Scouting for Boys, secara umum membahas tentang sikap tanggung jawab bermasyarakat, yakni...', '["A. Kewirausahaan","B. Keterampilan Militer","C. Kewarganegaraan (Citizenship)","D. Kepemimpinan Politik"]'::jsonb, 'C. Kewarganegaraan (Citizenship)'),
(5, 'Inti dari jiwa kewarganegaraan seorang Pramuka adalah kemauannya untuk memahami sejarah, pemerintahan, dan hukum bangsanya, agar kelak ia menjadi...', '["A. Pejabat tinggi negara","B. Prajurit militer yang tangguh","C. Warga negara yang aktif dan bermanfaat bagi negaranya","D. Warga yang diam dan tidak peduli"]'::jsonb, 'C. Warga negara yang aktif dan bermanfaat bagi negaranya'),
(5, 'Semboyan kepanduan utama yang diperkenalkan Baden-Powell dalam buku ini, yang wajib dipraktikkan baik dalam kesiapan fisik maupun mental oleh pandu di seluruh dunia adalah...', '["A. Do Your Best","B. Be Prepared (Selalu Siap)","C. Duty to God","D. Help Others"]'::jsonb, 'B. Be Prepared (Selalu Siap)'),
(5, 'Pesan moral secara keseluruhan dari Scouting for Boys yang tercantum di Bab 5 Boyman adalah membentuk remaja agar tidak hanya menjadi sosok petualang alam bebas, tetapi juga menjadi...', '["A. Prajurit tempur yang tak kenal takut","B. Pengusaha sukses dan kaya raya","C. Pria yang bertanggung jawab, mandiri, dan berkarakter mulia","D. Ilmuwan yang cerdas di laboratorium"]'::jsonb, 'C. Pria yang bertanggung jawab, mandiri, dan berkarakter mulia'),
(9, 'Pengertian berkemah dalam kepramukaan pada dasarnya adalah...', '["A. Tidur di hotel berbintang","B. Menginap di rumah teman","C. Kegiatan hidup di alam bebas dengan menggunakan tenda sebagai tempat berlindung","D. Belajar di dalam kelas"]'::jsonb, 'C. Kegiatan hidup di alam bebas dengan menggunakan tenda sebagai tempat berlindung'),
(9, 'Salah satu sasaran dan motivasi utama dari kegiatan berkemah bagi anggota Pramuka adalah...', '["A. Mencari harta karun","B. Melatih kemandirian, gotong royong, dan kedisiplinan di alam terbuka","C. Menghindari tugas sekolah","D. Menguji kekuatan fisik secara ekstrem"]'::jsonb, 'B. Melatih kemandirian, gotong royong, dan kedisiplinan di alam terbuka'),
(9, 'Tahap pertama yang mutlak harus dilakukan sebelum menyelenggarakan kegiatan perkemahan adalah...', '["A. Langsung mendirikan tenda","B. Mencari kayu bakar","C. Menyusun Perencanaan dan Persiapan (surat izin, lokasi, anggaran)","D. Membeli makanan ringan"]'::jsonb, 'C. Menyusun Perencanaan dan Persiapan (surat izin, lokasi, anggaran)'),
(9, 'Syarat utama tapak kemah (lokasi perkemahan) yang baik dan aman adalah...', '["A. Dekat dengan jurang","B. Berada di tengah jalan setapak","C. Dekat dengan sumber air yang bersih dan aman dari bahaya alam","D. Di bawah pohon yang sudah lapuk"]'::jsonb, 'C. Dekat dengan sumber air yang bersih dan aman dari bahaya alam'),
(9, 'Mengapa mendirikan tenda di dasar cekungan (lembah sempit) sangat dilarang dalam aturan perkemahan?', '["A. Udara terlalu panas","B. Risiko tertimpa pohon","C. Risiko terjebak banjir bandang / aliran air","D. Tanah terlalu keras"]'::jsonb, 'A. Sangat berbahaya jika terjadi hujan lebat karena rawan banjir bandang/genangan air'),
(9, 'Mendirikan tenda di bawah pohon tua yang sudah lapuk sangat dihindari karena...', '["A. Terlalu gelap","B. Mengundang serangga","C. Risiko pohon tumbang / patah menimpa tenda","D. Udara menjadi lembap"]'::jsonb, 'A. Rawan tertimpa dahan atau pohon tumbang jika ada angin kencang'),
(9, 'Arah pintu tenda yang ideal saat didirikan di alam bebas sebaiknya...', '["A. Menghadap ke arah datangnya angin","B. Membelakangi arah hembusan angin","C. Menghadap ke arah matahari terbenam","D. Menghadap jalan utama"]'::jsonb, 'A. Membelakangi atau menyamping dari arah hembusan angin utama'),
(9, 'Tujuan utama membuat parit kecil di sekeliling tenda saat berkemah adalah...', '["A. Mencegah hewan buas masuk","B. Sebagai batas wilayah tenda","C. Mengalirkan air hujan agar tidak menggenangi lantai tenda","D. Tempat membuang sampah organik"]'::jsonb, 'A. Mencegah air hujan masuk/menggenangi bagian dalam tenda'),
(9, 'Tenda darurat sementara yang dibuat dari bahan alam atau jas hujan (ponco) dinamakan...', '["A. Dome","B. Prisma","C. Bivak","D. Pleton"]'::jsonb, 'C. Bivak'),
(9, 'Tenda standar beregu yang sering digunakan oleh Pramuka Penggalang, bentuknya seperti rumah dengan atap segitiga disebut...', '["A. Tenda Prisma (Tenda Regu)","B. Tenda Dome","C. Tenda Lorong (Tunnel)","D. Tenda Peleton"]'::jsonb, 'A. Tenda Prisma (Tenda Regu)'),
(9, 'Agar patok (pasak) tenda menancap kuat menahan tarikan tali, kemiringan pasak yang ditancapkan ke tanah sebaiknya bersudut...', '["A. 90 derajat tegak lurus","B. 45-60 derajat berlawanan arah tarikan tali","C. Mendatar sejajar tanah","D. 45 derajat searah tarikan tali"]'::jsonb, 'A. Miring 45-60 derajat berlawanan dengan arah tarikan tali tenda'),
(9, 'Simpul yang paling tepat digunakan untuk mengikatkan tali tenda pada pasak agar mudah dikencangkan dan dikendurkan adalah...', '["A. Simpul Mati","B. Simpul Tali Tenda (Taut-line hitch)","C. Simpul Pangkal","D. Simpul Delapan"]'::jsonb, 'A. Simpul Tali Tenda (Taut-line Hitch)'),
(9, 'Perlengkapan perkemahan dibagi menjadi dua macam, yaitu...', '["A. Perlengkapan Memasak dan Tidur","B. Perlengkapan Pribadi (Perorangan) dan Perlengkapan Regu (Kelompok)","C. Perlengkapan Medis dan Navigasi","D. Perlengkapan Penting dan Tidak Penting"]'::jsonb, 'B. Perlengkapan Pribadi (Perorangan) dan Perlengkapan Regu (Kelompok)'),
(9, 'Berikut ini yang termasuk ke dalam Perlengkapan Pribadi saat berkemah adalah...', '["A. Tenda, panci, dan kompor","B. Pakaian ganti, sleeping bag, alat mandi, dan obat pribadi","C. Bendera regu dan tongkat","D. Kotak P3K regu dan golok"]'::jsonb, 'B. Pakaian ganti, sleeping bag, alat mandi, dan obat pribadi'),
(9, 'Berikut ini yang termasuk ke dalam Perlengkapan Regu adalah...', '["A. Baju seragam dan sikat gigi","B. Jas hujan ponco dan sepatu","C. Tenda, alat masak regu (nesting), dan kotak P3K regu","D. Piring plastik dan gelas"]'::jsonb, 'C. Tenda, alat masak regu (nesting), dan kotak P3K regu'),
(9, 'Alat pelindung tubuh dari suhu dingin saat tidur di dalam tenda yang bentuknya seperti kepompong disebut...', '["A. Matras","B. Flysheet","C. Sleeping Bag (Kantong Tidur)","D. Bivak"]'::jsonb, 'C. Sleeping Bag (Kantong Tidur)'),
(9, 'Alat berupa alas tidur berbahan busa/spons yang berfungsi menahan hawa dingin dari tanah agar tidak langsung mengenai tubuh disebut...', '["A. Groundsheet","B. Matras","C. Tikar","D. Karpet"]'::jsonb, 'B. Matras'),
(9, 'Tas besar khusus untuk membawa perlengkapan berkemah yang bentuknya dirancang mengikuti anatomi punggung disebut...', '["A. Tas Jinjing","B. Ransel (Carrier / Backpack)","C. Koper","D. Tas Selempang"]'::jsonb, 'B. Ransel (Carrier / Backpack)'),
(9, 'Prinsip dasar saat melakukan "Packing" (mengepak barang ke dalam ransel) agar tidak membuat punggung cepat lelah adalah...', '["A. Barang berat ditaruh di bawah","B. Barang berat ditaruh di sisi luar ransel","C. Barang berat ditaruh di atas, barang ringan di bawah dan menempel punggung","D. Asal masuk tanpa aturan"]'::jsonb, 'C. Barang berat ditaruh di atas, barang ringan di bawah dan menempel punggung'),
(9, 'Selain masalah berat, prinsip "Packing" yang baik untuk melindungi barang dari hujan adalah...', '["A. Menyemprotkan cairan anti air","B. Menggunakan ransel mahal","C. Melapisi bagian dalam ransel dengan kantong plastik sampah (Trash Bag) besar sebelum diisi barang","D. Menjemur ransel setiap hari"]'::jsonb, 'C. Melapisi bagian dalam ransel dengan kantong plastik sampah (Trash Bag) besar sebelum diisi barang'),
(9, 'Jas hujan berukuran besar berbentuk kelelawar yang dapat dialihfungsikan sebagai atap bivak darurat dinamakan...', '["A. Mantel","B. Jas Hujan Setelan","C. Ponco","D. Jaket Gunung"]'::jsonb, 'C. Ponco'),
(9, 'Syarat bahan makanan yang ideal untuk dibawa saat perkemahan adalah...', '["A. Cepat busuk dan berat","B. Mahal dan susah dimasak","C. Praktis, awet/tahan lama, bernilai gizi tinggi, dan mudah dimasak","D. Makanan cepat saji berkuah"]'::jsonb, 'C. Praktis, awet/tahan lama, bernilai gizi tinggi, dan mudah dimasak'),
(9, 'Alat masak portabel berbahan aluminium yang sering digunakan oleh militer dan pramuka karena bisa disusun menjadi satu wadah ringkas disebut...', '["A. Panci Teflon","B. Wajan","C. Nesting","D. Rantang"]'::jsonb, 'C. Nesting'),
(9, 'Lokasi yang TEPAT untuk menyalakan perapian atau kompor saat berkemah adalah...', '["A. Di dalam tenda saat hujan","B. Di bawah jemuran baju basah","C. Di luar tenda pada tempat terbuka dan aman dari tiupan angin kencang atau dedaunan kering","D. Tepat di samping dinding tenda"]'::jsonb, 'C. Di luar tenda pada tempat terbuka dan aman dari tiupan angin kencang atau dedaunan kering'),
(9, 'Hal yang mutlak DILARANG dilakukan di dalam tenda karena sangat berbahaya adalah...', '["A. Menyalakan api, kompor, lentera minyak, atau lilin","B. Bermain kartu","C. Bercerita sebelum tidur","D. Mengganti pakaian basah"]'::jsonb, 'A. Menyalakan api, kompor, lentera minyak, atau lilin'),
(9, 'Pembuatan fasilitas MCK (Mandi Cuci Kakus) darurat di area kemah harus berjarak minimal...', '["A. 2 meter dari tenda","B. 5 meter dari sungai","C. 15-20 meter dari sumber air agar tidak tercemar","D. 50 meter dari tenda"]'::jsonb, 'A. 15-20 meter dari sumber air agar tidak mencemari mata air'),
(9, 'Manajemen sampah di area perkemahan untuk jenis sampah anorganik (plastik, kaleng, kaca) yang paling benar adalah...', '["A. Dibakar bersama sampah daun","B. Dikubur di dalam tanah","C. Dibawa kembali turun untuk dibuang ke tempat sampah","D. Dibuang ke semak-semak tersembunyi"]'::jsonb, 'A. Dikumpulkan dalam kantong sampah lalu dibawa turun/pulang (Pack it in, Pack it out)'),
(9, 'Sampah organik (sisa makanan) di area perkemahan sebaiknya...', '["A. Dibuang sembarangan","B. Dibakar sampai habis","C. Dikubur dalam lubang kecil yang tertutup rapat agak jauh dari tenda agar tidak mengundang hewan","D. Dibuang ke dalam sungai"]'::jsonb, 'C. Dikubur dalam lubang kecil yang tertutup rapat agak jauh dari tenda agar tidak mengundang hewan'),
(9, 'Saat mengambil air minum dari sungai atau mata air alam, langkah wajib yang harus dilakukan sebelum meminumnya adalah...', '["A. Langsung diminum saja","B. Disaring dengan kain lalu direbus hingga mendidih (matang) untuk membunuh bakteri","C. Diendapkan selama 1 jam","D. Diberi garam sedikit"]'::jsonb, 'B. Disaring dengan kain lalu direbus hingga mendidih (matang) untuk membunuh bakteri'),
(9, 'Api unggun dalam kegiatan perkemahan memiliki fungsi utama sebagai...', '["A. Tempat membakar sampah plastik","B. Menakut-nakuti hewan","C. Sarana persaudaraan, kehangatan, dan pertunjukan seni","D. Sinyal bahaya darurat"]'::jsonb, 'C. Sarana persaudaraan, kehangatan, dan pertunjukan seni'),
(9, 'Aturan utama dalam membuat api unggun di alam bebas agar tidak merusak lingkungan adalah...', '["A. Menggunakan bensin sebanyak-banyaknya","B. Menebang pohon hidup","C. Membuat alas perapian (dari tanah/batu) atau tidak merusak area vegetasi di bawahnya","D. Membuatnya sekecil mungkin"]'::jsonb, 'C. Membuat alas perapian (dari tanah/batu) atau tidak merusak area vegetasi di bawahnya'),
(9, 'Pakaian lapangan yang ideal untuk berkemah adalah...', '["A. Kaos tipis yang mudah robek","B. Pakaian berbahan katun/ripstop yang menyerap keringat, kuat, dan cepat kering (PDL)","C. Celana Jeans tebal","D. Jaket kulit tebal"]'::jsonb, 'B. Pakaian berbahan katun/ripstop yang menyerap keringat, kuat, dan cepat kering (PDL)'),
(9, 'Mengapa celana berbahan Jeans/Denim SANGAT TIDAK disarankan dipakai untuk kegiatan kemah di alam bebas?', '["A. Warnanya mudah pudar","B. Terlalu tipis dan mudah robek","C. Berat, kaku, menahan hawa panas, dan sulit kering jika basah (memicu hipotermia)","D. Harganya mahal"]'::jsonb, 'A. Berat, tidak menyerap keringat, susah bergerak, dan sangat lama kering jika basah (bisa memicu hipotermia)'),
(9, 'Jenis alas kaki yang paling aman untuk kegiatan perkemahan dan penjelajahan adalah...', '["A. Sandal jepit","B. Sepatu kets lari","C. Sepatu lapangan/gunung yang menutupi mata kaki (Boot/Trekking Shoes)","D. Sepatu pantofel"]'::jsonb, 'C. Sepatu lapangan/gunung yang menutupi mata kaki (Boot/Trekking Shoes)'),
(9, 'Lembaran kain sintetis kedap air yang sering dipasang di atas tenda untuk menahan air hujan atau dibuat sebagai atap teras dinamakan...', '["A. Groundsheet","B. Matras","C. Flysheet","D. Ponco"]'::jsonb, 'C. Flysheet'),
(9, 'Alat kedap air yang diletakkan di bawah (lantai dasar) tenda agar uap air dari tanah tidak tembus ke dalam dinamakan...', '["A. Groundsheet / Terpal","B. Flysheet","C. Selimut","D. Nesting"]'::jsonb, 'A. Groundsheet / Terpal'),
(9, 'Aturan keamanan saat memegang dan berjalan membawa senjata tajam (golok/pisau) di perkemahan adalah...', '["A. Diayun-ayunkan agar terlihat gagah","B. Memegang bagian mata pisaunya langsung","C. Memegang bagian gagang dengan sisi tajam menghadap ke belakang/bawah, atau dimasukkan ke dalam sarungnya","D. Dilempar-lempar ke udara"]'::jsonb, 'C. Memegang bagian gagang dengan sisi tajam menghadap ke belakang/bawah, atau dimasukkan ke dalam sarungnya'),
(9, 'Saat ada anggota yang bertugas piket jaga malam, posisi jaga yang paling benar adalah...', '["A. Tidur nyenyak","B. Berjaga sendiri di tempat gelap","C. Berjaga secara bergantian dan tidak jauh dari api/sumber cahaya darurat","D. Masuk ke dalam tenda orang lain"]'::jsonb, 'C. Berjaga secara bergantian dan tidak jauh dari api/sumber cahaya darurat'),
(9, 'Jika tenda bocor parah di tengah hujan badai malam hari dan seluruh pakaian basah kuyup, ancaman kesehatan paling berbahaya adalah...', '["A. Masuk angin biasa","B. Flu","C. Hipotermia","D. Demam berdarah"]'::jsonb, 'C. Hipotermia'),
(9, 'Etika perkemahan saat malam hari (Quiet Hours) mengharuskan seluruh anggota untuk...', '["A. Bernyanyi dengan gitar sekeras mungkin","B. Menyalakan musik EDM","C. Menghentikan aktivitas berisik dan beristirahat agar tidak mengganggu makhluk hidup dan tenda lain","D. Berteriak-teriak memanggil teman"]'::jsonb, 'C. Menghentikan aktivitas berisik dan beristirahat agar tidak mengganggu makhluk hidup dan tenda lain'),
(9, 'Langkah pertama saat akan membongkar tenda di akhir kegiatan kemah adalah...', '["A. Langsung mencabut pasak tenda","B. Melipat tenda yang masih berdiri","C. Mengeluarkan dan membersihkan seluruh barang dari dalam tenda","D. Menggulung tali tenda secara acak"]'::jsonb, 'C. Mengeluarkan dan membersihkan seluruh barang dari dalam tenda'),
(9, 'Syarat utama sebelum melipat kain tenda untuk disimpan ke dalam tas adalah...', '["A. Tenda harus dicuci dengan sabun wangi","B. Tenda harus dalam keadaan benar-benar kering agar tidak berjamur","C. Tenda harus disetrika terlebih dahulu","D. Tenda harus ditaburi bedak anti serangga"]'::jsonb, 'B. Tenda harus dalam keadaan benar-benar kering agar tidak berjamur'),
(9, 'Prinsip pencinta alam "Leave No Trace" (Jangan tinggalkan jejak) mengajarkan kita untuk...', '["A. Meninggalkan tulisan nama kita di batang pohon","B. Membiarkan kondisi tapak kemah sama bersihnya atau lebih bersih daripada saat kita baru datang","C. Membuang sampah plastik ke sungai agar hanyut","D. Membakar semua barang yang tidak dibawa pulang"]'::jsonb, 'B. Membiarkan kondisi tapak kemah sama bersihnya atau lebih bersih daripada saat kita baru datang'),
(9, 'Kotak atau tas darurat berukuran kecil berisi perlengkapan bertahan hidup esensial (seperti korek anti air, kail pancing, pisau lipat, plester) dinamakan...', '["A. Kotak P3K","B. Survival Kit","C. Tas Pinggang","D. Nesting Set"]'::jsonb, 'B. Survival Kit'),
(9, 'Tindakan yang benar jika tersesat saat melakukan kegiatan penjelajahan di sekitar perkemahan adalah...', '["A. Berlari panik mencari jalan keluar","B. Menangis sekencang-kencangnya","C. STOP (Stop, Think, Observe, Plan) dan tidak panik","D. Membuang semua barang bawaan agar ringan"]'::jsonb, 'C. STOP (Stop, Think, Observe, Plan) dan tidak panik'),
(9, 'Fungsi menggunakan pakaian lengan panjang saat menerobos semak/hutan di area kemah adalah...', '["A. Agar terlihat rapi","B. Menahan dingin, melindungi dari duri, goresan ranting, dan gigitan serangga","C. Agar tidak kepanasan","D. Untuk menutupi kotoran"]'::jsonb, 'B. Menahan dingin, melindungi dari duri, goresan ranting, dan gigitan serangga'),
(9, 'Tanda yang dibuat oleh anggota Pramuka menggunakan batu, ranting, atau goresan tanah untuk memberi petunjuk arah di alam bebas disebut...', '["A. Sandi Rahasia","B. Tanda Peringatan","C. Tanda Jejak","D. Peta Topografi"]'::jsonb, 'C. Tanda Jejak'),
(9, 'Sikap mental yang paling dituntut dari seorang pemimpin regu saat perkemahan dilanda cuaca buruk adalah...', '["A. Menangis ketakutan","B. Bersembunyi sendirian","C. Tenang, mengambil keputusan cepat untuk mengamankan anggota, dan menjaga moral regu","D. Menyalahkan panitia perkemahan"]'::jsonb, 'C. Tenang, mengambil keputusan cepat untuk mengamankan anggota, dan menjaga moral regu'),
(9, 'Obat yang wajib dibawa secara pribadi (tidak boleh mengandalkan regu) saat berkemah adalah...', '["A. Parasetamol cair","B. Betadine dan kapas","C. Obat penyakit khusus/alergi yang diidap oleh diri sendiri","D. Minyak angin"]'::jsonb, 'C. Obat penyakit khusus/alergi yang diidap oleh diri sendiri'),
(9, 'Tujuan akhir setelah kembali dari kegiatan berkemah adalah...', '["A. Langsung tidur seharian penuh","B. Membuang semua peralatan karena kotor","C. Melakukan evaluasi kegiatan, membersihkan dan merawat kembali peralatan agar siap dipakai di kemudian hari","D. Membakar tenda yang sudah rusak"]'::jsonb, 'C. Melakukan evaluasi kegiatan, membersihkan dan merawat kembali peralatan agar siap dipakai di kemudian hari'),
(12, 'Kata "Sandi" berasal dari bahasa Sanskerta, yang memiliki arti...', '["A. Pesan rahasia","B. Rahasia","C. Menyembunyikan","D. Tulisan sandi"]'::jsonb, 'B. Rahasia'),
(12, 'Fungsi utama mempelajari sandi dalam kegiatan kepramukaan adalah untuk...', '["A. Menyembunyikan makanan dari teman","B. Menghibur diri saat bosan","C. Melatih daya ingat, kecerdasan, dan ketelitian","D. Mengerjakan tugas sekolah dengan rahasia"]'::jsonb, 'C. Melatih daya ingat, kecerdasan, dan ketelitian'),
(12, 'Penemu sistem telegraf dan kode Morse adalah seorang seniman dan penemu asal Amerika yang bernama...', '["A. Thomas Alva Edison","B. Alexander Graham Bell","C. Samuel F.B. Morse","D. Guglielmo Marconi"]'::jsonb, 'C. Samuel F.B. Morse'),
(12, 'Kode Morse pertama kali ditemukan dan digunakan secara praktis pada tahun...', '["A. 1827","B. 1837","C. 1847","D. 1857"]'::jsonb, 'B. 1837'),
(12, 'Dalam standar internasional, perbandingan durasi waktu antara bunyi/simbol "titik" dan "garis" pada sandi Morse adalah...', '["A. 1 : 2","B. 1 : 3","C. 2 : 3","D. 1 : 4"]'::jsonb, 'B. 1 : 3'),
(12, 'Huruf yang direpresentasikan dengan satu titik (.) dalam sandi Morse adalah...', '["A. I","B. E","C. S","D. H"]'::jsonb, 'B. E'),
(12, 'Huruf yang direpresentasikan dengan satu garis (-) dalam sandi Morse adalah...', '["A. O","B. M","C. T","D. N"]'::jsonb, 'C. T'),
(12, 'Kode Morse untuk huruf "A" adalah...', '["A. -.","B. .-","C. ..","D. --"]'::jsonb, 'B. .-'),
(12, 'Kode Morse untuk huruf "B" adalah...', '["A. -...","B. ...-","C. -.-.","D. .--."]'::jsonb, 'A. -...'),
(12, 'Sinyal marabahaya darurat atau minta tolong standar internasional (SOS) dalam sandi Morse ditulis dengan...', '["A. --- ... ---","B. ... --- ...","C. ..- -.. ..-","D. -.- ... -.-"]'::jsonb, 'B. ... --- ...'),
(12, 'Kode Morse (...--) melambangkan angka...', '["A. 1","B. 2","C. 3","D. 4"]'::jsonb, 'C. 3'),
(12, 'Kode Morse (---..) melambangkan angka...', '["A. 6","B. 7","C. 8","D. 9"]'::jsonb, 'C. 8'),
(12, 'Kode Morse (----.) melambangkan angka...', '["A. 6","B. 7","C. 8","D. 9"]'::jsonb, 'D. 9'),
(12, 'Tanda pemisah antar kata saat menulis sandi Morse di atas kertas biasanya menggunakan tanda...', '["A. Garis bawah (_)","B. Tanda hubung (-)","C. Garis miring ganda (//)","D. Tanda titik koma (;)"]'::jsonb, 'C. Garis miring ganda (//)'),
(12, 'Dalam pengiriman pesan Morse, tanda untuk memulai panggilan atau "Attention" biasanya menggunakan kode...', '["A. -.-.-","B. .-...-","C. -.-.-.","D. ...-.-"]'::jsonb, 'C. -.-.-.'),
(12, 'Isyarat bahwa "Pesan Selesai" (End of Message) dalam pengiriman Morse ditandai dengan kode gabungan huruf AR, yaitu...', '["A. ...-.-","B. .-.-.","C. -...-","D. .-..-"]'::jsonb, 'B. .-.-.'),
(12, 'Jika pengirim melakukan kesalahan saat mengirim sandi Morse, ia memberikan isyarat salah (E 8 kali) yang berbunyi...', '["A. ........","B. --------","C. .-.-.-.-","D. -.-.-.-."]'::jsonb, 'A. ........'),
(12, 'Huruf yang secara kode berlawanan dengan A (.-) adalah N, yaitu...', '["A. .-","B. -.","C. ..","D. --"]'::jsonb, 'B. -.'),
(12, 'Huruf "O" dalam sandi Morse terdiri dari...', '["A. Tiga titik","B. Tiga garis (---)","C. Dua titik satu garis","D. Satu titik dua garis"]'::jsonb, 'B. Tiga garis (---)'),
(12, 'Huruf "S" dalam sandi Morse terdiri dari...', '["A. Tiga titik (...)","B. Tiga garis (---)","C. Dua titik dan satu garis (..-)","D. Dua garis dan satu titik (--.)"]'::jsonb, 'A. Tiga titik (...)'),
(12, 'Gabungan huruf S dan O membentuk kata SOS, yang secara universal berarti isyarat...', '["A. Pesan Selesai","B. Menunggu Instruksi","C. Darurat / Marabahaya","D. Perhatian"]'::jsonb, 'C. Darurat / Marabahaya'),
(12, 'Huruf "I" dalam sandi Morse terdiri dari...', '["A. Satu titik (.)","B. Dua titik (..)","C. Tiga titik (...)","D. Empat titik (....)"]'::jsonb, 'B. Dua titik (..)'),
(12, 'Huruf "M" dalam sandi Morse terdiri dari...', '["A. Satu garis (-)","B. Dua garis (--)","C. Tiga garis (---)","D. Empat garis (----)"]'::jsonb, 'B. Dua garis (--)'),
(12, 'Huruf "C" dalam sandi Morse dituliskan dengan kode...', '["A. -.-.","B. --.-","C. -..-","D. .--."]'::jsonb, 'A. -.-.'),
(12, 'Huruf "D" dalam sandi Morse dituliskan dengan kode...', '["A. -..","B. ..-","C. -.-.","D. .--."]'::jsonb, 'A. -..'),
(12, 'Berlawanan dengan huruf D (-..), huruf "U" dalam sandi morse adalah...', '["A. -..","B. ..-","C. .--.","D. --.-"]'::jsonb, 'B. ..-'),
(12, 'Huruf "F" dalam sandi Morse adalah...', '["A. ..-.","B. .-..","C. --.-","D. .--."]'::jsonb, 'A. ..-.'),
(12, 'Huruf "G" dalam sandi Morse adalah...', '["A. --.","B. .--","C. -..-","D. -.--"]'::jsonb, 'A. --.'),
(12, 'Huruf "H" dalam sandi Morse adalah...', '["A. ....","B. -...","C. ...-","D. ..-."]'::jsonb, 'A. ....'),
(12, 'Huruf "J" dalam sandi Morse adalah...', '["A. .---","B. ---.","C. -.-.","D. .--."]'::jsonb, 'A. .---'),
(12, 'Huruf "K" dalam sandi Morse adalah...', '["A. -.-","B. .-.","C. --.","D. ..-"]'::jsonb, 'A. -.-'),
(12, 'Huruf "L" dalam sandi Morse adalah...', '["A. .-..","B. ..-.","C. .--.","D. -..-"]'::jsonb, 'A. .-..'),
(12, 'Huruf "P" dalam sandi Morse adalah...', '["A. .--.","B. --.-","C. .-..","D. -..-"]'::jsonb, 'A. .--.'),
(12, 'Huruf "Q" dalam sandi Morse adalah...', '["A. --.-","B. .--.","C. -.--","D. -.-."]'::jsonb, 'A. --.-'),
(12, 'Huruf "R" dalam sandi Morse adalah...', '["A. .-.","B. -.-","C. ..-","D. --."]'::jsonb, 'A. .-.'),
(12, 'Huruf "V" dalam sandi Morse adalah...', '["A. ...-","B. -...","C. .---","D. ---."]'::jsonb, 'A. ...-'),
(12, 'Huruf "W" dalam sandi Morse adalah...', '["A. .--","B. --.","C. ..-","D. -.."]'::jsonb, 'A. .--'),
(12, 'Huruf "X" dalam sandi Morse adalah...', '["A. -..-","B. .--.","C. --.-","D. -.--"]'::jsonb, 'A. -..-'),
(12, 'Huruf "Y" dalam sandi Morse adalah...', '["A. -.--","B. --.-","C. -..-","D. .--."]'::jsonb, 'A. -.--'),
(12, 'Huruf "Z" dalam sandi Morse adalah...', '["A. --..","B. ..--","C. -..-","D. --.-"]'::jsonb, 'A. --..'),
(12, 'Angka 1 dalam sandi Morse ditulis dengan urutan...', '["A. .----","B. ----.","C. ..---","D. ---.."]'::jsonb, 'A. .----'),
(12, 'Angka 5 dalam sandi Morse adalah...', '["A. .....","B. -----","C. .----","D. ----."]'::jsonb, 'A. .....'),
(12, 'Angka 0 dalam sandi Morse adalah...', '["A. .....","B. -----","C. .----","D. ----."]'::jsonb, 'B. -----'),
(12, 'Tanda koma (,) dalam tulisan Morse diwakili dengan gabungan...', '["A. --..--","B. ..--..","C. .-.-.-","D. -.-.-."]'::jsonb, 'A. --..--'),
(12, 'Tanda tanya (?) dalam tulisan Morse diwakili dengan gabungan...', '["A. --..--","B. ..--..","C. .-.-.-","D. -.-.-."]'::jsonb, 'B. ..--..'),
(12, 'Saat mengirim kode Morse dengan peluit, bunyi tiupan pendek secara internasional mewakili...', '["A. Titik","B. Garis","C. Jeda","D. Spasi"]'::jsonb, 'A. Titik'),
(12, 'Saat mengirim kode Morse dengan peluit, bunyi tiupan panjang yang keras mewakili...', '["A. Titik","B. Garis","C. Jeda","D. Spasi"]'::jsonb, 'B. Garis'),
(12, 'Isyarat komunikasi "Tunggu" (AS) yang dikirimkan kepada lawan saat transmisi Morse adalah...', '["A. .-...","B. -...-","C. .-.-.","D. -.-.-"]'::jsonb, 'A. .-...'),
(12, 'Isyarat "Mengerti / Pesan Diterima" (R) yang dikirimkan kembali oleh penerima pesan adalah...', '["A. .-.","B. -.-","C. ..-","D. --."]'::jsonb, 'A. .-.'),
(12, 'Cara paling mudah dan umum yang diajarkan dalam pramuka untuk menghafal sandi Morse adalah metode pengelompokan huruf yang saling...', '["A. Dihafalkan sesuai abjad","B. Berlawanan / Berkebalikan (Contoh: A >< N)","C. Dinyanyikan dengan lagu","D. Ditulis berulang-ulang"]'::jsonb, 'B. Berlawanan / Berkebalikan (Contoh: A >< N)'),
(15, 'Gambar seluruh atau sebagian permukaan bumi yang diproyeksikan pada bidang datar dengan perbandingan skala tertentu disebut...', '["A. Peta","B. Globe","C. Atlas","D. Maket"]'::jsonb, 'A. Peta'),
(15, 'Jenis peta yang sangat penting bagi Pramuka karena menggambarkan tinggi rendahnya permukaan bumi (relief) secara detail adalah...', '["A. Peta Buta","B. Peta Navigasi Udara","C. Peta Topografi","D. Peta Politik"]'::jsonb, 'C. Peta Topografi'),
(15, 'Kumpulan penjelasan tentang arti simbol-simbol dan warna yang terdapat pada peta disebut...', '["A. Indeks Kontur","B. Skala Peta","C. Legenda Peta","D. Garis Astronomis"]'::jsonb, 'C. Legenda Peta'),
(15, 'Angka yang menunjukkan perbandingan antara jarak di atas peta dengan jarak sebenarnya di lapangan disebut...', '["A. Koordinat","B. Deklinasi","C. Skala","D. Resection"]'::jsonb, 'C. Skala'),
(15, 'Peta dengan skala 1 : 25.000 berarti 1 cm pada peta mewakili jarak sebenarnya di lapangan sejauh...', '["A. 25 meter","B. 250 meter","C. 2,5 kilometer","D. 25 kilometer"]'::jsonb, 'B. 250 meter'),
(15, 'Jika jarak antara titik A dan B di peta topografi (skala 1:50.000) adalah 4 cm, maka jarak sebenarnya di lapangan adalah...', '["A. 200 meter","B. 2 kilometer","C. 4 kilometer","D. 20 kilometer"]'::jsonb, 'B. 2 kilometer'),
(15, 'Skala peta yang ditunjukkan dalam bentuk garis lurus yang terbagi menjadi beberapa ruas dengan ukuran satuan jarak tertentu disebut...', '["A. Skala Angka","B. Skala Pecahan","C. Skala Garis (Grafis)","D. Skala Verbal"]'::jsonb, 'C. Skala Garis (Grafis)'),
(15, 'Garis khayal melingkar pada peta topografi yang menghubungkan titik-titik dengan ketinggian yang sama dari permukaan laut disebut...', '["A. Garis Bujur","B. Garis Lintang","C. Garis Kontur","D. Garis Khatulistiwa"]'::jsonb, 'C. Garis Kontur'),
(15, 'Ciri khas utama dari garis kontur adalah jika jarak antar garisnya tergambar sangat rapat, hal itu menunjukkan bentuk medan yang...', '["A. Landai / Datar","B. Curam / Terjal","C. Bergelombang","D. Dataran Rendah"]'::jsonb, 'B. Curam / Terjal'),
(15, 'Jika jarak antar garis kontur di peta terlihat renggang atau saling berjauhan, itu menandakan bentuk medan yang...', '["A. Landai / Datar","B. Curam / Terjal","C. Bergelombang","D. Berbukit"]'::jsonb, 'A. Landai / Datar'),
(15, 'Garis kontur yang membentuk pola huruf "V" atau "U" terbalik yang menjorok ke arah ketinggian (menunjuk ke tempat yang lebih tinggi) menandakan bentang alam berupa...', '["A. Punggungan (Sadel)","B. Puncak bukit","C. Lembah / Aliran Sungai","D. Dataran tinggi"]'::jsonb, 'C. Lembah / Aliran Sungai'),
(15, 'Garis kontur yang membentuk pola huruf "V" atau "U" yang menjorok ke arah tempat yang lebih rendah menandakan bentang alam berupa...', '["A. Lembah / Aliran Sungai","B. Punggungan (Sadel) / Punggung Bukit","C. Puncak gunung","D. Kawah"]'::jsonb, 'B. Punggungan (Sadel) / Punggung Bukit'),
(15, 'Garis kontur yang tergambar berupa lingkaran-lingkaran kecil konsentris yang semakin mengecil di bagian tengah biasanya menandakan...', '["A. Danau","B. Lembah","C. Puncak bukit / Gunung","D. Punggungan"]'::jsonb, 'C. Puncak bukit / Gunung'),
(15, 'Jika ada garis kontur melingkar namun memiliki garis-garis rambut kecil (tick marks) yang mengarah ke bagian dalam lingkaran, itu menandakan...', '["A. Puncak Gunung","B. Danau","C. Depresi / Kawah / Cekungan","D. Dataran tinggi"]'::jsonb, 'C. Depresi / Kawah / Cekungan'),
(15, 'Selisih ketinggian atau jarak vertikal antara satu garis kontur dengan garis kontur di sebelahnya disebut...', '["A. Interval Kontur","B. Indeks Kontur","C. Skala Vertikal","D. Ketinggian Mutlak"]'::jsonb, 'A. Interval Kontur'),
(15, 'Garis kontur yang biasanya dicetak lebih tebal dan disertai angka penunjuk ketinggian untuk mempermudah pembacaan peta disebut...', '["A. Garis Utama","B. Indeks Kontur","C. Kontur Tambahan","D. Kontur Pembantu"]'::jsonb, 'B. Indeks Kontur'),
(15, 'Sistem garis kisi-kisi (grid) yang membagi peta menjadi kotak-kotak untuk menentukan posisi secara akurat dinamakan koordinat...', '["A. UTM (Universal Transverse Mercator)","B. Geografis","C. Kartesius","D. Bujur Lintang"]'::jsonb, 'A. UTM (Universal Transverse Mercator)'),
(15, 'Garis vertikal (membujur dari bawah ke atas) pada sistem koordinat kotak (grid) peta yang angkanya dibaca pertama kali (dibaca ke arah Timur) disebut...', '["A. Northing","B. Easting","C. Longitude","D. Latitude"]'::jsonb, 'B. Easting'),
(15, 'Garis horizontal (melintang dari kiri ke kanan) pada sistem koordinat grid peta yang angkanya dibaca kedua (dibaca ke arah Utara) disebut...', '["A. Easting","B. Northing","C. Longitude","D. Latitude"]'::jsonb, 'B. Northing'),
(15, 'Aturan emas (golden rule) dalam membaca koordinat grid di atas peta topografi adalah...', '["A. Baca garis vertikal dulu (ke kanan), lalu horizontal (ke atas)","B. Baca vertikal ke kiri, lalu atas","C. Baca horizontal dulu (ke atas), lalu vertikal (ke kanan)","D. Baca menyilang dari titik 0"]'::jsonb, 'A. Baca dari kiri ke kanan (Easting), lalu dari bawah ke atas (Northing)'),
(15, 'Jika kita diminta menunjuk titik dengan koordinat 6 digit (contoh: 456 789), ini berarti tingkat ketelitian pencarian lokasi tersebut mencapai area seluas...', '["A. 1 meter persegi","B. 10 meter persegi","C. 100 meter persegi","D. 1 kilometer persegi"]'::jsonb, 'C. 100 meter persegi'),
(15, 'Arah Utara yang ditunjukkan oleh garis-garis grid vertikal lurus ke atas pada peta disebut...', '["A. Utara Sebenarnya (True North)","B. Utara Magnetis (Magnetic North)","C. Utara Peta (Grid North)","D. Utara Kutub"]'::jsonb, 'C. Utara Peta (Grid North)'),
(15, 'Arah Utara yang mengarah tepat ke Kutub Utara bumi (poros rotasi) disebut...', '["A. Utara Peta (Grid North)","B. Utara Magnetis (Magnetic North)","C. Utara Sebenarnya (True North)","D. Utara Relatif"]'::jsonb, 'C. Utara Sebenarnya (True North)'),
(15, 'Dalam legenda peta topografi standar, warna COKLAT umumnya digunakan untuk menggambarkan...', '["A. Perairan","B. Garis ketinggian (Kontur) dan bentang alam darat","C. Kawasan hutan","D. Jalan raya utama"]'::jsonb, 'B. Garis ketinggian (Kontur) dan bentang alam darat'),
(15, 'Warna HIJAU pada peta topografi selalu mengindikasikan adanya...', '["A. Perairan / Laut","B. Bentang alam tinggi","C. Kawasan vegetasi / Hutan / Perkebunan","D. Pemukiman penduduk"]'::jsonb, 'C. Kawasan vegetasi / Hutan / Perkebunan'),
(15, 'Warna BIRU pada peta digunakan secara universal untuk menyimbolkan unsur...', '["A. Daratan tinggi","B. Hutan lebat","C. Hidrografi / Perairan (Sungai, danau, rawa, laut)","D. Jalan tol"]'::jsonb, 'C. Hidrografi / Perairan (Sungai, danau, rawa, laut)'),
(15, 'Warna MERAH pada peta topografi sering kali dikhususkan untuk menandakan unsur penting buatan manusia, yaitu...', '["A. Bangunan militer","B. Hutan produksi","C. Jalan raya utama / aspal","D. Jalur pendakian"]'::jsonb, 'C. Jalan raya utama / aspal'),
(15, 'Warna HITAM dalam peta biasanya digunakan untuk mencetak...', '["A. Kontur interval","B. Sungai dan danau","C. Simbol pemukiman, gedung, jalan setapak, dan tulisan","D. Area hutan pinus"]'::jsonb, 'C. Simbol pemukiman, gedung, jalan setapak, dan tulisan'),
(15, 'Simbol berupa titik hitam dengan bentuk segitiga atau lingkaran disertai angka (misal: ▲ 2100) di peta menunjukkan...', '["A. Lokasi perkemahan","B. Titik kumpul","C. Titik Triangulasi / Ketinggian mutlak (Spot Height)","D. Mata air panas"]'::jsonb, 'C. Titik Triangulasi / Ketinggian mutlak (Spot Height)'),
(15, 'Tindakan menyamakan posisi arah Utara pada peta agar sejajar dengan arah Utara sebenarnya di lapangan (menggunakan kompas) disebut...', '["A. Navigasi Darat","B. Plotting Peta","C. Orientasi Peta","D. Membaca Peta"]'::jsonb, 'C. Orientasi Peta'),
(15, 'Syarat pertama yang harus dilakukan sebelum melakukan teknik navigasi Resection atau Intersection di lapangan adalah...', '["A. Melakukan Orientasi Peta terlebih dahulu","B. Mencari mata air terdekat","C. Mendirikan tenda","D. Mengukur skala peta"]'::jsonb, 'A. Melakukan Orientasi Peta terlebih dahulu'),
(15, 'Teknik navigasi untuk menentukan titik koordinat posisi kita sendiri di atas peta, dengan cara membidik dua objek alam yang sudah diketahui di peta, disebut...', '["A. Intersection","B. Resection","C. Orientasi","D. Azimuth"]'::jsonb, 'B. Resection'),
(15, 'Teknik navigasi untuk mencari koordinat posisi objek lain (sasaran) yang belum diketahui di peta, dengan membidiknya dari dua titik stasiun yang berbeda, disebut...', '["A. Resection","B. Intersection","C. Plotting","D. Back Azimuth"]'::jsonb, 'B. Intersection'),
(15, 'Alat ukur sederhana berbentuk busur derajat berbentuk kotak persegi transparan yang digunakan untuk menghitung sudut dan koordinat langsung di atas peta disebut...', '["A. Kompas Bidik","B. Altimeter","C. Protractor (Busur Peta)","D. Curvimeter"]'::jsonb, 'C. Protractor (Busur Peta)'),
(15, 'Alat mekanis kecil dengan roda bergerigi yang dijalankan menyusuri rute lengkung di peta (seperti sungai atau jalan berliku) untuk menghitung jarak disebut...', '["A. Altimeter","B. Protractor","C. Planimeter","D. Curvimeter"]'::jsonb, 'D. Curvimeter'),
(15, 'Penyimpangan sudut yang terjadi antara garis Utara Peta (Grid) dengan Utara Magnetis (Kompas) di suatu wilayah disebut...', '["A. Deklinasi Magnetis","B. Inclinasi","C. Deviasi Kompas","D. Resection Sudut"]'::jsonb, 'A. Deklinasi Magnetis'),
(15, 'Jika kita melipat peta topografi untuk dibawa di saku lapangan, cara melipat yang benar agar peta tidak cepat rusak dan mudah dibaca adalah...', '["A. Dilipat menjadi gulungan panjang","B. Dilipat sembarangan yang penting muat di saku","C. Dilipat seperti kipas / akordion (zig-zag) dengan bagian yang akan dibaca menghadap luar","D. Dipotong-potong kecil sesuai daerah"]'::jsonb, 'C. Dilipat seperti kipas / akordion (zig-zag) dengan bagian yang akan dibaca menghadap luar'),
(15, 'Saat membaca peta, jika kita berjalan mengikuti punggungan bukit (ridge), maka di peta kita sebenarnya sedang melangkah memotong garis-garis kontur yang berbentuk...', '["A. Lingkaran sempurna","B. Huruf V yang menjorok ke atas","C. U atau V terbalik (menjorok ke bawah)","D. Garis lurus horizontal"]'::jsonb, 'C. U atau V terbalik (menjorok ke bawah)'),
(15, 'Kumpulan peta dalam satu wujud buku besar dinamakan...', '["A. Globe","B. Atlas","C. Ensiklopedia","D. Direktori"]'::jsonb, 'B. Atlas'),
(15, 'Jika tidak memiliki meteran, seorang Pramuka dapat memperkirakan jarak di peta dengan di lapangan menggunakan teknik...', '["A. Melempar batu dan menghitung detiknya","B. Menebak dari ukuran pohon","C. Menghitung jumlah langkah kaki ganda (Pacing)","D. Mengukur dengan ranting kayu"]'::jsonb, 'C. Menghitung jumlah langkah kaki ganda (Pacing)'),
(15, 'Garis Khatulistiwa (Equator) yang membelah bumi menjadi Utara dan Selatan ditarik pada derajat...', '["A. 0 derajat lintang","B. 90 derajat lintang","C. 180 derajat bujur","D. 0 derajat bujur"]'::jsonb, 'A. 0 derajat lintang'),
(15, 'Garis Bujur Utama (Prime Meridian) yang menjadi titik 0 derajat dan patokan waktu bumi disepakati melintasi kota...', '["A. Paris, Prancis","B. New York, Amerika Serikat","C. Greenwich, London, Inggris","D. Tokyo, Jepang"]'::jsonb, 'C. Greenwich, London, Inggris'),
(15, 'Informasi mengenai tahun pembuatan atau pembaruan peta (update) biasanya dapat ditemukan di...', '["A. Tepat di tengah peta","B. Di samping legenda","C. Bagian tepi bawah luar / Margin bawah peta","D. Di pojok kanan atas saja"]'::jsonb, 'C. Bagian tepi bawah luar / Margin bawah peta'),
(15, 'Navigasi yang dilakukan di malam hari tanpa kompas dapat mengandalkan Rasi Bintang Pari (Crux) untuk menentukan arah...', '["A. Utara","B. Selatan","C. Timur","D. Barat"]'::jsonb, 'B. Selatan'),
(15, 'Navigasi malam hari di belahan bumi utara/tengah dapat menentukan arah Utara dengan mencari konstelasi bintang...', '["A. Rasi Bintang Pari","B. Ursa Major (Bintang Biduk) / Polaris","C. Bintang Kejora","D. Rasi Scorpio"]'::jsonb, 'B. Ursa Major (Bintang Biduk) / Polaris'),
(15, 'Alasan mengapa lumut pada pohon lebih sering tumbuh tebal di sisi tertentu (sebagai navigasi darurat penunjuk Timur/Barat) adalah...', '["A. Karena sisi tersebut selalu menghadap ke atas","B. Karena sisi tersebut sering digesek binatang","C. Karena sisi tersebut paling sedikit/banyak terkena paparan sinar matahari langsung (kondisi lembap)","D. Karena sisi tersebut terkena angin kencang"]'::jsonb, 'C. Karena sisi tersebut paling sedikit/banyak terkena paparan sinar matahari langsung (kondisi lembap)'),
(15, 'Metode navigasi alam menggunakan bayangan tongkat kayu yang ditancapkan tegak di tanah pada siang hari disebut metode...', '["A. Bayangan semu","B. Sundial","C. Proyeksi bayangan","D. Bivak navigasi"]'::jsonb, 'A. Sundial / Metode Bayangan Matahari'),
(15, 'Pada peta dengan sistem koordinat grid geografis, Lintang Utara disingkat dengan huruf...', '["A. S (South)","B. E (East)","C. LU (N - North)","D. W (West)"]'::jsonb, 'C. LU (N - North)'),
(15, 'Satu derajat (1°) dalam sistem koordinat Geografis (DMS) dibagi lagi menjadi...', '["A. 10 menit","B. 60 menit","C. 100 menit","D. 360 menit"]'::jsonb, 'B. 60 menit'),
(15, 'Sistem Penentuan Posisi Global yang mengandalkan perangkat elektronik untuk menerima sinyal satelit navigasi bumi disebut...', '["A. Radar","B. Sonar","C. GPS (Global Positioning System)","D. Radio Transmiter"]'::jsonb, 'C. GPS (Global Positioning System)'),
(20, 'Sandi yang menggunakan bentuk garis vertikal, horizontal, dan titik sebagai pengganti huruf disebut...', '["A. Sandi Kotak 1","B. Sandi Kotak 2","C. Sandi Kotak 3","D. Sandi Rumput"]'::jsonb, 'A. Sandi Kotak 1'),
(20, 'Sandi Kotak 1 terdiri dari dua macam bentuk pola kerangka dasar, yaitu...', '["A. Palang tegak lurus dan silang (X)","B. Segitiga dan lingkaran","C. Belah ketupat dan segi enam","D. Kotak besar dan kotak kecil"]'::jsonb, 'A. Palang tegak lurus dan silang (X)'),
(20, 'Dalam Sandi Kotak 1, masing-masing ruangan kotak pada kerangka palang maksimal diisi oleh...', '["A. 1 huruf","B. 2 huruf","C. 3 huruf","D. 4 huruf"]'::jsonb, 'B. 2 huruf'),
(20, 'Dalam Sandi Kotak 1, huruf "B" digambarkan dengan bentuk sudut siku-siku terbuka ke atas-kanan, ditambah dengan...', '["A. Tanpa titik","B. 1 titik","C. 2 titik","D. 3 titik"]'::jsonb, 'B. 1 titik'),
(20, 'Dalam Sandi Kotak 1, huruf "A" digambarkan dengan bentuk sudut siku-siku terbuka ke atas-kanan, ditambah dengan...', '["A. Tanpa titik","B. 1 titik","C. 2 titik","D. 3 titik"]'::jsonb, 'A. Tanpa titik'),
(20, 'Dalam Sandi Kotak 1, huruf "N" yang berada di kerangka silang (X) digambarkan dengan bentuk huruf V yang terbuka ke bawah, ditambah dengan...', '["A. Tanpa titik","B. 1 titik","C. 2 titik","D. 3 titik"]'::jsonb, 'A. Tanpa titik'),
(20, 'Perbedaan utama antara Sandi Kotak 1 dan Sandi Kotak 2 (versi Boyman) terletak pada penempatan huruf, yaitu...', '["A. Sandi Kotak 2 tidak menggunakan titik","B. Setiap kotak pada Sandi Kotak 2 berisi 3 huruf dan maksimal menggunakan 2 titik","C. Sandi Kotak 2 bentuk kerangkanya lingkaran","D. Sandi Kotak 2 hanya dibaca dari belakang"]'::jsonb, 'B. Setiap kotak pada Sandi Kotak 2 berisi 3 huruf dan maksimal menggunakan 2 titik'),
(20, 'Dalam Sandi Kotak 2, huruf "C" ditandai dengan kotak yang sama dengan huruf A dan B, namun dibedakan menggunakan...', '["A. Tanpa titik","B. Menggunakan 1 titik","C. Menggunakan 2 titik","D. Menggunakan garis coret"]'::jsonb, 'C. Menggunakan 2 titik'),
(20, 'Sandi Kotak 3 memiliki bentuk dasar kerangka yang unik dan sedikit rumit, yaitu berbentuk susunan...', '["A. Lingkaran berlapis","B. Belah ketupat (segi empat silang)","C. Trapesium ganda","D. Segitiga piramida"]'::jsonb, 'B. Belah ketupat (segi empat silang)'),
(20, 'Sandi Rumput pada dasarnya merupakan bentuk kamuflase atau aplikasi visual murni dari...', '["A. Sandi Kotak","B. Sandi Semaphore","C. Sandi Morse","D. Sandi Braille"]'::jsonb, 'C. Sandi Morse'),
(20, 'Pada Sandi Rumput, lambang titik (.) pada kode morse digambarkan dengan wujud...', '["A. Rumput tinggi","B. Rumput pendek","C. Rumput bercabang","D. Bunga rumput"]'::jsonb, 'B. Rumput pendek'),
(20, 'Pada Sandi Rumput, lambang garis (-) pada kode morse digambarkan dengan wujud...', '["A. Rumput tinggi","B. Rumput pendek","C. Rumput ganda","D. Akar rumput"]'::jsonb, 'A. Rumput tinggi'),
(20, 'Sandi yang mengubah urutan abjad sedemikian rupa sehingga abjad dibagi dua, huruf "A" dibaca "N", "B" dibaca "O", dan seterusnya, disebut...', '["A. Sandi AZ","B. Sandi AN","C. Sandi Balik","D. Sandi Angka"]'::jsonb, 'B. Sandi AN'),
(20, 'Kata "PRAMUKA" jika dipecahkan menggunakan rumus abjad Sandi AN akan berbunyi...', '["A. CENZHXN","B. KIZNFPZ","C. QSBNVLB","D. OQZLTJZ"]'::jsonb, 'A. CENZHXN'),
(20, 'Sandi yang menukar huruf awal alfabet dengan huruf akhir (A menjadi Z, B menjadi Y, C menjadi X) disebut...', '["A. Sandi AN","B. Sandi Balik","C. Sandi AZ","D. Sandi Cermin"]'::jsonb, 'A. Sandi AZ / Sandi Balik Abjad'),
(20, 'Kata "PRAMUKA" jika dibaca ke dalam rumus Sandi AZ maka akan menjadi susunan huruf...', '["A. CENZHXN","B. KIZNFPZ","C. QSBNVLB","D. OQZLTJZ"]'::jsonb, 'B. KIZNFPZ'),
(20, 'Dalam Sandi Angka dasar, di mana A=1, B=2, dst., maka susunan kode 16-18-1-13-21-11-1 dibaca...', '["A. PANDU","B. PRAMUKA","C. BOYMAN","D. SIAGA"]'::jsonb, 'B. PRAMUKA'),
(20, 'Sandi Angka juga bisa divariasikan patokannya (misal awalan A=0). Jika A=0, maka huruf C adalah angka...', '["A. 1","B. 2","C. 3","D. 4"]'::jsonb, 'B. 2'),
(20, 'Sandi yang pengerjaannya menggunakan dua kata kunci yang digabungkan membentuk tabel baris dan kolom persilangan, disebut...', '["A. Sandi Jam","B. Sandi Koordinat","C. Sandi Kotak","D. Sandi Ular"]'::jsonb, 'B. Sandi Koordinat'),
(20, 'Dua buah kata yang paling sering dan umum dijadikan kata kunci dalam Sandi Koordinat Pramuka adalah...', '["A. GARUDA PANCASILA","B. MERAH PUTIH","C. TUNAS KELAPA","D. PANDU DUNIA"]'::jsonb, 'B. MERAH PUTIH'),
(20, 'Dalam Sandi Koordinat "MERAH PUTIH", huruf "M" mewakili posisi...', '["A. Baris pertama","B. Kolom pertama","C. Baris kedua","D. Kolom kedua"]'::jsonb, 'A. Baris pertama'),
(20, 'Sandi yang memanfaatkan patokan interval selisih waktu secara berurutan sebagai pengganti abjad alfabet disebut...', '["A. Sandi Geser","B. Sandi Waktu","C. Sandi Jam","D. Sandi Datar"]'::jsonb, 'C. Sandi Jam'),
(20, 'Pada Sandi Jam, jika disepakati pukul 08.00 adalah huruf A, dan interval beda waktu adalah 5 menit, maka huruf B ditulis pada...', '["A. 08.01","B. 08.05","C. 08.10","D. 08.15"]'::jsonb, 'B. 08.05'),
(20, 'Jika pukul 07.00 = A dengan interval waktu yang sama yaitu 5 menit, jam berapakah yang akan menunjukkan huruf C?', '["A. 07.05","B. 07.10","C. 07.15","D. 07.20"]'::jsonb, 'B. 07.10'),
(20, 'Sandi yang mengadopsi cara penulisan unsur rumus kimia, dan sebenarnya merupakan kamuflase lain dari sandi Morse, disebut...', '["A. Sandi Biologi","B. Sandi Fisika","C. Sandi Kimia","D. Sandi Matematika"]'::jsonb, 'C. Sandi Kimia'),
(20, 'Dalam ketentuan Sandi Kimia Pramuka, kelompok huruf Vokal (A, I, U, E, O) berfungsi menggantikan posisi...', '["A. Tanda Garis (-) pada Morse","B. Tanda Titik (.) pada Morse","C. Jeda antar huruf","D. Pemisah spasi"]'::jsonb, 'B. Tanda Titik (.) pada Morse'),
(20, 'Dalam Sandi Kimia, kelompok huruf Konsonan (B, C, D, F, dst) berfungsi menggantikan posisi...', '["A. Tanda Garis (-) pada Morse","B. Tanda Titik (.) pada Morse","C. Huruf besar","D. Angka numerik"]'::jsonb, 'A. Tanda Garis (-) pada Morse'),
(20, 'Kode Morse ".-" (Huruf A) jika diubah ke dalam Sandi Kimia bisa ditulis menjadi wujud kombinasi Vokal-Konsonan bebas, misalnya...', '["A. HO","B. OH","C. H2","D. O2"]'::jsonb, 'B. OH'),
(20, 'Sandi kata yang cara menyembunyikannya adalah dengan menyisipkan huruf/kata "AND" di antara abjad aslinya disebut...', '["A. Sandi Sisip","B. Sandi AND","C. Sandi OR","D. Sandi NOT"]'::jsonb, 'B. Sandi AND'),
(20, 'Sandi yang bentuk aslinya menyerupai lekukan garis-garis bergelombang tak terputus, di mana lekukan kecil adalah titik dan lekukan besar/runcing adalah garis, dinamakan...', '["A. Sandi Rumput","B. Sandi Sungai","C. Sandi Ular / Sandi Gergaji","D. Sandi Ombak"]'::jsonb, 'C. Sandi Ular / Sandi Gergaji'),
(20, 'Sandi yang cara membacanya sama dengan metode membaca aksara Arab, yaitu dibaca terbalik dari kanan ke kiri, disebut...', '["A. Sandi Arab","B. Sandi Terbalik","C. Sandi Kanan","D. Sandi Cermin"]'::jsonb, 'A. Sandi Arab'),
(20, 'Sebuah pesan tertulis "AKUMARP", jika dipecahkan menggunakan kaidah Sandi Arab akan dapat dibaca menjadi kata...', '["A. KOMPUTER","B. PRAMUKA","C. PANDEGA","D. BOYMAN"]'::jsonb, 'B. PRAMUKA'),
(20, 'Sandi yang cara membacanya memutar seperti cangkang kerang dari tengah ke luar atau luar ke dalam berlawanan jarum jam disebut...', '["A. Sandi Obat Nyamuk","B. Sandi Siput","C. Sandi Putar","D. Sandi Melingkar"]'::jsonb, 'B. Sandi Siput'),
(20, 'Sandi yang menggunakan titik-titik timbul untuk membantu penyandang tunanetra membaca, yang diciptakan di Prancis adalah...', '["A. Louis Braille","B. Helen Keller","C. Morse","D. Semaphore"]'::jsonb, 'A. Louis Braille'),
(20, 'Susunan titik pada Sandi Braille dibentuk berdasarkan pola sebuah kotak imajiner yang berukuran...', '["A. 2 kolom dan 2 baris (4 titik)","B. 2 kolom dan 3 baris (total 6 titik posisi)","C. 3 kolom dan 3 baris (9 titik)","D. 1 kolom dan 4 baris (4 titik)"]'::jsonb, 'B. 2 kolom dan 3 baris (total 6 titik posisi)'),
(20, 'Isyarat komunikasi jarak jauh yang menggunakan peraga sepasang bendera tangan dan sering masuk dalam materi wawasan komunikasi Pramuka disebut...', '["A. Morse Bendera","B. Semaphore","C. Sinyal Asap","D. Heliograph"]'::jsonb, 'B. Semaphore'),
(20, 'Ukuran standar bendera Semaphore yang biasa digunakan oleh Pramuka Penggalang adalah persegi dengan ukuran...', '["A. 30 x 30 cm","B. 45 x 45 cm","C. 60 x 60 cm","D. 90 x 90 cm"]'::jsonb, 'B. 45 x 45 cm'),
(20, 'Warna standar untuk bendera Semaphore agar mudah terlihat dari jarak jauh adalah perpaduan menyilang dari warna...', '["A. Hitam dan Putih","B. Merah dan Putih","C. Merah dan Kuning","D. Biru dan Kuning"]'::jsonb, 'C. Merah dan Kuning'),
(20, 'Dalam Sandi Kotak 1, huruf "Z" digambarkan menempati kerangka silang (X) pada sudut bawah dengan ditambahkan...', '["A. Tanpa titik","B. 1 titik","C. 2 titik","D. 3 titik"]'::jsonb, 'B. 1 titik'),
(20, 'Sandi yang memanipulasi abjad Morse ke dalam bentuk angka pembilang dan penyebut pecahan matematika disebut...', '["A. Sandi Hitung","B. Sandi Pecahan / Sandi Matematika","C. Sandi Aljabar","D. Sandi Rumus"]'::jsonb, 'B. Sandi Pecahan / Sandi Matematika'),
(20, 'Pada variasi Sandi Angka, jika disepakati A=3, B=4, maka huruf D akan ditulis menggunakan angka...', '["A. 5","B. 6","C. 7","D. 8"]'::jsonb, 'B. 6'),
(20, 'Huruf "E" dalam kode morse hanya terdiri dari satu titik. Dalam Sandi Kimia, huruf E dapat diwakilkan cukup dengan satu huruf saja, misalnya...', '["A. Huruf Konsonan, contohnya K","B. Huruf Vokal, contohnya O","C. Huruf ganda, contohnya CH","D. Angka 1"]'::jsonb, 'B. Huruf Vokal, contohnya O'),
(20, 'Huruf "T" dalam kode morse hanya terdiri dari satu garis. Dalam Sandi Kimia, huruf T dapat diwakilkan cukup dengan satu huruf, misalnya...', '["A. Huruf Vokal, contohnya O","B. Huruf Konsonan, contohnya K","C. Simbol kimia H2O","D. Angka 0"]'::jsonb, 'B. Huruf Konsonan, contohnya K'),
(20, 'Syarat utama dua buah kata yang akan dijadikan kunci dalam tabel baris/kolom Sandi Koordinat adalah gabungan katanya harus terdiri dari...', '["A. 5 huruf sama","B. 10 huruf tanpa ada huruf ganda yang sama","C. 15 huruf dengan vokal bebas","D. 26 huruf alfabet lengkap"]'::jsonb, 'B. 10 huruf tanpa ada huruf ganda yang sama'),
(20, 'Kata "Sandi" itu sendiri berarti...', '["A. Rahasia","B. Pesan","C. Tulisan","D. Isyarat"]'::jsonb, 'A. Rahasia'),
(20, 'Tujuan asli dibentuknya sandi atau kriptografi pada zaman dahulu yang menginspirasi kepramukaan adalah...', '["A. Untuk permainan anak-anak","B. Untuk menulis puisi cinta","C. Mengirim pesan rahasia di masa perang/kritis agar tidak dapat dibaca oleh pihak musuh","D. Untuk menipu raja"]'::jsonb, 'C. Mengirim pesan rahasia di masa perang/kritis agar tidak dapat dibaca oleh pihak musuh'),
(20, 'Jika Sandi Jam dimulai pukul 10.00 = A, dan beda waktu intervalnya dinaikkan menjadi 10 menit, maka pukul 10.20 menunjukkan huruf...', '["A. B","B. C","C. D","D. E"]'::jsonb, 'B. C'),
(20, 'Sandi rahasia unik yang menggunakan bentuk gambar tongkat orang menari dengan posisi lengan berbeda-beda (Dancing Men) terinspirasi dari novel karya...', '["A. J.K. Rowling","B. Sir Arthur Conan Doyle (Sherlock Holmes)","C. Agatha Christie","D. Ian Fleming"]'::jsonb, 'B. Sir Arthur Conan Doyle (Sherlock Holmes)'),
(20, '"P-E-M-B-I-N-A" jika ditulis menggunakan rumus Sandi Arab akan menjadi susunan...', '["A. A-N-I-B-M-E-P","B. P-A-N-I-B-E-M","C. B-I-N-A-P-E-M","D. P-M-B-N-E-I-A"]'::jsonb, 'A. A-N-I-B-M-E-P'),
(20, 'Salah satu Syarat Kecakapan Umum (SKU) Pramuka Penggalang mewajibkan anggotanya untuk dapat memahami, membaca, dan mengirimkan pesan isyarat dasar yaitu...', '["A. Sandi Kotak dan Sandi Angka","B. Morse dan Semaphore","C. Sandi Jam dan Sandi Kimia","D. Sandi Arab dan Sandi Ular"]'::jsonb, 'B. Morse dan Semaphore'),
(24, 'Singkatan dari P3K adalah...', '["A. Pertolongan Pertama Pada Kecelakaan","B. Pertolongan Pertama Penanganan Korban","C. Perawatan Pertama Pada Keadaan Darurat","D. Pemberian Pertolongan Pasca Kecelakaan"]'::jsonb, 'A. Pertolongan Pertama Pada Kecelakaan'),
(24, 'Tujuan utama dari pemberian P3K adalah...', '["A. Menggantikan peran dokter seutuhnya","B. Menyembuhkan luka secara total","C. Menyelamatkan nyawa dan mencegah kondisi korban memburuk","D. Memberi ketenangan kepada keluarga korban"]'::jsonb, 'C. Menyelamatkan nyawa dan mencegah kondisi korban memburuk'),
(24, 'Langkah pertama yang harus dilakukan saat menemukan korban kecelakaan adalah...', '["A. Memastikan keamanan penolong, lokasi, dan korban (Aman Diri)","B. Langsung mengangkat korban","C. Berteriak meminta bantuan warga","D. Memberikan minum kepada korban"]'::jsonb, 'A. Memastikan keamanan penolong, lokasi, dan korban (Aman Diri)'),
(24, 'Pembalut segitiga yang sangat sering digunakan dalam P3K Pramuka disebut...', '["A. Perban Gulung","B. Mitela","C. Kasa Steril","D. Plester"]'::jsonb, 'B. Mitela'),
(24, 'Alat keras/kaku yang digunakan untuk menahan tulang yang patah agar tidak bergerak disebut...', '["A. Mitela","B. Kruk","C. Bidai / Spalk","D. Tandu"]'::jsonb, 'C. Bidai / Spalk'),
(24, 'Pertolongan pertama pada korban mimisan yang benar adalah...', '["A. Menengadahkan kepala jauh ke belakang","B. Memasukkan kapas ke dalam lubang hidung","C. Menundukkan kepala ke depan dan menjepit cuping hidung","D. Berbaring telentang"]'::jsonb, 'C. Menundukkan kepala ke depan dan menjepit cuping hidung'),
(24, 'Pendarahan arteri ditandai dengan ciri-ciri...', '["A. Darah merembes perlahan berwarna merah gelap","B. Darah memancar seirama denyut jantung dan berwarna merah terang","C. Darah mengalir lancar berwarna kehitaman","D. Darah menggumpal dan berbusa"]'::jsonb, 'B. Darah memancar seirama denyut jantung dan berwarna merah terang'),
(24, 'Cara menghentikan pendarahan luar yang paling efektif adalah dengan teknik...', '["A. Dicuci dengan air es","B. Balut tekan (tekan langsung di atas luka)","C. Mengikat tourniquet sekuat mungkin","D. Diolesi obat merah tebal-tebal"]'::jsonb, 'B. Balut tekan (tekan langsung di atas luka)'),
(24, 'Simpul yang digunakan untuk mengakhiri balutan mitela agar mudah dilepas adalah...', '["A. Simpul Anyam","B. Simpul Pangkal","C. Simpul Mati","D. Simpul Tiang"]'::jsonb, 'C. Simpul Mati'),
(24, 'Kondisi penurunan suhu tubuh secara drastis akibat cuaca dingin di gunung disebut...', '["A. Hipertermia","B. Dehidrasi","C. Hipotermia","D. Asfiksia"]'::jsonb, 'C. Hipotermia'),
(24, 'Pertolongan pertama pada luka bakar ringan (derajat 1) adalah...', '["A. Diolesi odol/pasta gigi","B. Dialiri air bersih mengalir selama 10-15 menit","C. Ditempelkan es batu langsung","D. Dipecahkan gelembungnya"]'::jsonb, 'B. Dialiri air bersih mengalir selama 10-15 menit'),
(24, 'Alat untuk mengangkut korban kecelakaan secara darurat yang dibuat dari dua tongkat dan tali disebut...', '["A. Matras","B. Bivak Darurat","C. Tandu Darurat (Dragbar)","D. Ransel"]'::jsonb, 'C. Tandu Darurat (Dragbar)'),
(24, 'Jumlah ikatan minimal pada pemasangan bidai untuk patah tulang tungkai bawah adalah...', '["A. Satu ikatan di tengah","B. Minimal melewati dua sendi","C. Tiga ikatan di satu titik","D. Empat ikatan bebas"]'::jsonb, 'B. Minimal melewati dua sendi'),
(24, 'Korban pingsan sebaiknya diposisikan telentang dengan posisi kaki...', '["A. Lebih tinggi dari kepala (Elevasi)","B. Lebih rendah dari kepala","C. Sejajar dengan kepala","D. Ditekuk di perut"]'::jsonb, 'A. Lebih tinggi dari kepala (Elevasi)'),
(24, 'Isi kotak P3K yang berfungsi untuk membersihkan luka dari kuman adalah...', '["A. Parasetamol","B. Antiseptik (Betadine/Rivanol)","C. Oralit","D. Minyak Kayu Putih"]'::jsonb, 'B. Antiseptik (Betadine/Rivanol)'),
(24, 'Penyakit yang disebabkan oleh gigitan nyamuk Aedes Aegypti adalah...', '["A. Malaria","B. Cikungunya","C. Demam Berdarah (Dengue)","D. Tifus"]'::jsonb, 'C. Demam Berdarah (Dengue)'),
(24, 'Cara menangani kaki yang terkilir (kram/keseleo) dengan metode RICE, singkatan dari...', '["A. Rest, Ice, Compression, Elevation","B. Run, Ice, Cool, Elevate","C. Rest, Iron, Cold, Energy","D. Race, Immobilize, Compression, Eat"]'::jsonb, 'A. Rest, Ice, Compression, Elevation'),
(24, 'Pertolongan pertama jika seseorang tersedak makanan dan sulit bernapas adalah dengan...', '["A. Memberi minum air hangat","B. Menyuruhnya berbaring telentang","C. Manuver Heimlich (hentakan pada perut)","D. Menampar pipinya"]'::jsonb, 'C. Manuver Heimlich (hentakan pada perut)'),
(24, 'Obat yang digunakan untuk mengurangi rasa sakit kepala atau demam ringan adalah...', '["A. Parasetamol","B. Antasida","C. Amoksisilin","D. Oralit"]'::jsonb, 'A. Parasetamol'),
(24, 'Untuk mengganti cairan tubuh yang hilang akibat diare, sebaiknya diberikan...', '["A. Air kelapa muda","B. Susu hangat","C. Oralit","D. Teh manis pekat"]'::jsonb, 'C. Oralit'),
(24, 'Pembalutan pada luka di kepala biasanya menggunakan mitela yang dilipat menjadi bentuk...', '["A. Pita kecil","B. Persegi empat","C. Segitiga terbuka","D. Gulungan tabung"]'::jsonb, 'C. Segitiga terbuka'),
(24, 'Luka yang disebabkan oleh benda tumpul dan menyebabkan memar kebiruan disebut luka...', '["A. Luka Sayat","B. Luka Tusuk","C. Luka Memar (Contusio)","D. Luka Bakar"]'::jsonb, 'C. Luka Memar (Contusio)'),
(24, 'Tindakan RJP (Resusitasi Jantung Paru) dilakukan pada korban yang...', '["A. Pingsan biasa","B. Patah tulang rusuk","C. Henti napas dan henti jantung","D. Pendarahan di kepala"]'::jsonb, 'C. Henti napas dan henti jantung'),
(24, 'Pada saat memindahkan korban dengan tandu, posisi kepala korban sebaiknya berada di...', '["A. Depan (searah jalan)","B. Belakang (berlawanan arah jalan)","C. Bebas","D. Diikat di tengah"]'::jsonb, 'B. Belakang (berlawanan arah jalan)'),
(24, 'Warna kotak P3K standar biasanya adalah...', '["A. Merah dengan palang putih","B. Hitam dengan lambang medis","C. Putih dengan tanda palang merah/hijau","D. Biru tua"]'::jsonb, 'C. Putih dengan tanda palang merah/hijau'),
(24, 'Pertolongan pertama pada gigitan ular yang paling tepat adalah...', '["A. Mengisap bisa dari luka menggunakan mulut","B. Mengikat tourniquet mati di pangkal lengan/kaki","C. Imobilisasi (tidak menggerakkan bagian yang digigit) dan bawa ke RS","D. Mengoleskan lumpur"]'::jsonb, 'C. Imobilisasi (tidak menggerakkan bagian yang digigit) dan bawa ke RS'),
(24, 'Pembalut elastis (Elastic Bandage) sangat baik digunakan untuk menangani...', '["A. Membalut luka bakar luas","B. Terkilir / Cedera sendi","C. Menghapus darah","D. Membuat tandu"]'::jsonb, 'B. Terkilir / Cedera sendi'),
(24, 'Penyakit yang sering muncul di perkemahan akibat sanitasi buruk dan air kotor adalah...', '["A. Malaria","B. Diare","C. Demam Berdarah (Dengue)","D. Tifus"]'::jsonb, 'B. Diare'),
(24, 'Kasa steril diletakkan langsung di atas luka bertujuan untuk...', '["A. Mencegah rasa sakit","B. Menutup luka agar tidak infeksi dan menyerap darah","C. Menahan tulang agar tidak geser","D. Mempercepat pembekuan darah secara kimiawi"]'::jsonb, 'B. Menutup luka agar tidak infeksi dan menyerap darah'),
(24, 'Berapa jumlah penolong yang ideal untuk mengangkat tandu darurat?', '["A. 1 orang","B. 2 orang","C. 2-4 orang","D. 6-8 orang"]'::jsonb, 'C. 2-4 orang'),
(24, 'Alat untuk mengukur suhu tubuh manusia disebut...', '["A. Stetoskop","B. Termometer","C. Tensi Darah","D. Barometer"]'::jsonb, 'B. Termometer'),
(24, 'Suhu tubuh normal manusia berkisar antara...', '["A. 34-35 derajat Celcius","B. 36-37 derajat Celcius","C. 38-39 derajat Celcius","D. 39-40 derajat Celcius"]'::jsonb, 'B. 36-37 derajat Celcius'),
(24, 'Tindakan yang harus dihindari saat menolong korban patah tulang adalah...', '["A. Memasang bidai","B. Menenangkan korban","C. Mencoba meluruskan posisi tulang secara paksa","D. Menghentikan pendarahan luar jika ada"]'::jsonb, 'C. Mencoba meluruskan posisi tulang secara paksa'),
(24, 'Mencuci tangan sebelum makan dan setelah beraktivitas merupakan contoh...', '["A. Pemborosan air","B. Kebiasaan anak-anak","C. Perilaku Hidup Bersih dan Sehat (PHBS)","D. Syarat berkemah"]'::jsonb, 'C. Perilaku Hidup Bersih dan Sehat (PHBS)'),
(24, 'Cairan yang digunakan untuk mencuci mata jika kemasukan debu adalah...', '["A. Air sabun","B. Boorwater (Air steril pencuci mata)","C. Alkohol","D. Rivanol"]'::jsonb, 'A. Air bersih / Boorwater'),
(24, 'Pembalut Mitela dilipat menjadi "Gendongan" berfungsi untuk menyangga cedera pada...', '["A. Kaki","B. Perut","C. Lengan / Patah tulang tangan","D. Kepala"]'::jsonb, 'A. Lengan / Bahu'),
(24, 'Tanda-tanda seseorang mengalami syok (shock) adalah...', '["A. Wajah pucat, keringat dingin, denyut nadi cepat tapi lemah","B. Wajah memerah dan badan panas","C. Tertawa terus-menerus","D. Kulit membiru dan gatal-gatal"]'::jsonb, 'A. Nadi cepat dan lemah, kulit pucat, keringat dingin'),
(24, 'Zat racun dalam makanan dapat dinetralkan sementara (sebelum ke dokter) dengan meminum...', '["A. Air garam pekat","B. Kopi pahit","C. Susu steril atau air kelapa","D. Air jeruk nipis"]'::jsonb, 'A. Susu / Air kelapa'),
(24, 'Obat luar yang digunakan untuk meredakan gatal akibat gigitan serangga adalah...', '["A. Betadine","B. Salep Hidrokortison / Calamine","C. Rivanol","D. Obat Merah"]'::jsonb, 'A. Minyak Kayu Putih / Kaladin'),
(24, 'Luka tusuk akibat paku berkarat sangat berisiko menyebabkan penyakit...', '["A. Rabies","B. Polio","C. Tetanus","D. Demam Berdarah"]'::jsonb, 'C. Tetanus'),
(24, 'Pada RJP (CPR), rasio kompresi dada dan napas buatan untuk satu penolong adalah...', '["A. 15 kompresi : 2 napas","B. 30 kompresi : 2 napas","C. 5 kompresi : 1 napas","D. 10 kompresi : 2 napas"]'::jsonb, 'A. 30 : 2'),
(24, 'Pembalutan luka di lutut yang sedang ditekuk paling baik menggunakan teknik...', '["A. Balutan angka 8 (Figure of Eight)","B. Balutan melingkar","C. Balutan spiral","D. Balutan segitiga"]'::jsonb, 'A. Balutan angka delapan'),
(24, 'Bagian dari tas P3K yang digunakan untuk memotong perban atau pakaian korban adalah...', '["A. Pisau lipat","B. Gunting Verban","C. Silet","D. Cutter"]'::jsonb, 'B. Gunting Verban'),
(24, 'Untuk membersihkan luka yang kotor dari kerikil atau pasir digunakan...', '["A. Air alkohol","B. Betadine langsung","C. Air mengalir atau cairan infus (NaCl)","D. Minyak angin"]'::jsonb, 'A. Pinset dan air bersih'),
(24, 'Apa yang harus dilakukan jika korban tersambar petir?', '["A. Jangan disentuh karena masih menghantarkan listrik","B. Langsung diberikan RJP (Resusitasi Jantung Paru) jika henti napas/jantung","C. Disiram dengan air","D. Dikubur di dalam tanah"]'::jsonb, 'A. Segera periksa napas dan nadi, lakukan RJP jika perlu, dan bawa ke RS'),
(24, 'Gunting yang bagian ujungnya tumpul (Gunting Verban) bertujuan untuk...', '["A. Agar mudah disimpan","B. Agar tajam memotong tulang","C. Menghindari kulit korban ikut tergunting saat pakaian digunting","D. Untuk menggunting mitela saja"]'::jsonb, 'A. Mencegah kulit korban terluka saat menggunting perban'),
(24, 'Kesehatan lingkungan perkemahan dijaga dengan cara membuat lubang sampah sedalam...', '["A. 20 cm","B. Minimal 50 cm hingga 1 meter","C. 5 meter","D. Tidak perlu lubang"]'::jsonb, 'A. 50-100 cm (agar tidak dibongkar hewan)'),
(24, 'Obat yang digunakan untuk menolong sakit perut akibat maag adalah...', '["A. Parasetamol","B. Antasida","C. Oralit","D. Betadine"]'::jsonb, 'B. Antasida'),
(24, 'Mencuci luka dengan air sabun sangat disarankan khusus untuk luka akibat...', '["A. Sayatan pisau tajam","B. Luka bakar panas","C. Gigitan hewan (anjing/kucing) untuk cegah rabies","D. Lecet karena jatuh di aspal"]'::jsonb, 'C. Gigitan hewan (anjing/kucing) untuk cegah rabies'),
(24, 'Prinsip utama penolong P3K adalah...', '["A. Cepat dan Terburu-buru","B. Tenang, Cepat, Tepat, dan Tidak Panik","C. Menunggu dokter datang","D. Berteriak minta tolong"]'::jsonb, 'B. Tenang, Cepat, Tepat, dan Tidak Panik'),
(99, 'Gerakan kepanduan di Indonesia resmi diakui dan menjadi anggota WOSM (World Organization of the Scout Movement) pada tahun...', '["A. 1945","B. 1953","C. 1961","D. 1973"]'::jsonb, 'B. 1953'),
(99, 'Sifat kepramukaan yang berarti penyelenggaraannya disesuaikan dengan keadaan, kebutuhan, dan kepentingan masyarakat di negaranya adalah sifat...', '["A. Universal","B. Nasional","C. Internasional","D. Fleksibel"]'::jsonb, 'B. Nasional'),
(99, 'Semboyan Sistem Among "Ing Madyo Mangun Karso" memiliki arti seorang Pembina harus mampu...', '["A. Di depan memberikan teladan","B. Di tengah membangun kemauan/semangat","C. Di belakang memberikan dorongan","D. Mendidik dengan keras"]'::jsonb, 'B. Di tengah membangun kemauan/semangat'),
(99, 'Tanda Kecakapan Khusus (TKK) tingkat tertinggi yang bentuknya segilima beraturan adalah tingkat...', '["A. Purwa","B. Madya","C. Utama","D. Garuda"]'::jsonb, 'C. Utama'),
(99, 'Undang-Undang Republik Indonesia yang secara khusus mengatur tentang Gerakan Pramuka saat ini adalah...', '["A. UU No. 20 Tahun 2003","B. UU No. 12 Tahun 2010","C. UU No. 14 Tahun 2005","D. UU No. 40 Tahun 2009"]'::jsonb, 'B. UU No. 12 Tahun 2010'),
(99, 'Bapak Pandu Dunia (Chief Scout of the World) dan Bapak Pramuka Indonesia secara berurutan adalah...', '["A. Baden Powell dan Soekarno","B. William Smyth dan Ki Hajar Dewantara","C. Baden Powell dan Sri Sultan Hamengkubuwono IX","D. Lord Cecil dan H. Mutahar"]'::jsonb, 'C. Baden Powell dan Sri Sultan Hamengkubuwono IX'),
(99, 'Penggolongan usia Pramuka Penegak yang tepat adalah...', '["A. 7 - 10 tahun","B. 11 - 15 tahun","C. 16 - 20 tahun","D. 21 - 25 tahun"]'::jsonb, 'C. 16 - 20 tahun'),
(99, 'Meskipun lekat dengan dunia militer, ayah dari Baden-Powell sejatinya adalah seorang...', '["A. Laksamana Angkatan Laut","B. Guru Besar Geometri di Universitas Oxford","C. Dokter Bedah Kerajaan","D. Pendeta"]'::jsonb, 'B. Guru Besar Geometri di Universitas Oxford'),
(99, 'Suku-suku di Afrika memberikan julukan "Impeesa" kepada Baden-Powell, yang memiliki makna filosofis...', '["A. Singa yang perkasa","B. Burung elang yang bermata tajam","C. Serigala yang tidak pernah tidur","D. Ksatria putih"]'::jsonb, 'C. Serigala yang tidak pernah tidur'),
(99, 'Buku mahakarya Baden-Powell yang ditujukan khusus untuk golongan pemuda (Rover Scout) pada tahun 1922 berjudul...', '["A. Scouting for Boys","B. Aids to Scouting","C. The Jungle Book","D. Rovering to Success"]'::jsonb, 'D. Rovering to Success'),
(99, 'Kalung manik-manik kayu (Wood Badge) yang dikalungkan pada Pembina Pramuka lulusan kursus lanjutan berasal dari kalung pimpinan suku Afrika bernama...', '["A. Ashanti","B. Zulu","C. Dinizulu","D. Matabele"]'::jsonb, 'C. Dinizulu'),
(99, 'Pada batu nisan makam Baden-Powell di Nyeri, Kenya, terdapat tanda jejak kepanduan berupa lingkaran dengan titik di tengah yang memiliki arti rahasia...', '["A. Bahaya di depan","B. Saya telah pulang","C. Jalan terus","D. Ada air bersih"]'::jsonb, 'B. Saya telah pulang'),
(99, 'Pasukan kavaleri pertama yang ditempati Baden-Powell saat bertugas ke India dengan pangkat Pembantu Letnan adalah...', '["A. 5th Royal","B. 1st Infantry","C. 13th Hussars","D. Mafeking Corps"]'::jsonb, 'C. 13th Hussars'),
(99, 'Buku Scouting for Boys secara struktural dibagi ke dalam 26 bab khusus yang oleh Baden-Powell disebut dengan istilah...', '["A. Sesi Petualangan","B. Cerita Api Unggun (Campfire Yarns)","C. Panduan Rimba","D. Kode Kehormatan"]'::jsonb, 'B. Cerita Api Unggun (Campfire Yarns)'),
(99, 'Simpul yang paling tepat digunakan untuk menyambung dua utas tali yang ukurannya TIDAK SAMA besar dan dalam keadaan kering adalah...', '["A. Simpul Anyam (Sheet Bend)","B. Simpul Mati (Reef Knot)","C. Simpul Kembar","D. Simpul Tarik"]'::jsonb, 'A. Simpul Anyam (Sheet Bend)'),
(99, 'Prinsip konservasi dalam Cerita Api Unggun ke-15 melarang pandu membunuh binatang apa pun, KECUALI...', '["A. Binatang itu berbulu indah untuk dikoleksi","B. Saat sedang perlombaan berburu","C. Ketika terancam bahaya keselamatan atau terpaksa untuk bertahan hidup","D. Jika binatang tersebut cacat"]'::jsonb, 'C. Ketika terancam bahaya keselamatan atau terpaksa untuk bertahan hidup'),
(99, 'Tokoh orang suci pelindung Inggris yang dijadikan simbol ksatria kaum pandu di seluruh dunia (diperingati setiap 23 April) karena keberaniannya menumpas naga adalah...', '["A. Raja Arthur","B. Santo George (St. George)","C. Santo Petrus","D. Richard The Lionheart"]'::jsonb, 'B. Santo George (St. George)'),
(99, 'Tindakan yang Paling Tepat jika pakaian yang dikenakan tiba-tiba tersambar api menurut panduan P3K Scouting for Boys adalah...', '["A. Berlari mencari air sungai","B. Mengipasinya dengan daun","C. Berguling-guling di tanah atau membungkus rapat dengan selimut tebal","D. Menyemprotkan alkohol"]'::jsonb, 'C. Berguling-guling di tanah atau membungkus rapat dengan selimut tebal'),
(99, 'Inspirasi utama Baden-Powell tentang pentingnya pemuda bermula dari pasukan anak-anak saat pengepungan kota Mafeking yang dipimpin oleh...', '["A. Mayor Kenneth","B. Lord Edward Cecil","C. Jenderal Kitchener","D. Arthur Pearson"]'::jsonb, 'B. Lord Edward Cecil'),
(99, 'Mendirikan tenda di dasar cekungan (lembah sempit kering) sangat dilarang oleh aturan perkemahan tingkat lanjut karena risiko...', '["A. Udara terlalu panas saat siang","B. Angin puting beliung","C. Terjebak banjir bandang jika hujan lebat turun di hulu","D. Tanah longsor dari atas"]'::jsonb, 'C. Terjebak banjir bandang jika hujan lebat turun di hulu'),
(99, 'Agar pasak tenda menancap kuat dan tidak mudah tercabut oleh angin, kemiringan pasak ke dalam tanah harus membentuk sudut...', '["A. 90 derajat lurus","B. 45-60 derajat berlawanan dengan arah tarikan tali tenda","C. 45 derajat searah tarikan tali","D. Geletak mendatar"]'::jsonb, 'B. 45-60 derajat berlawanan dengan arah tarikan tali tenda'),
(99, 'Celana berbahan Jeans/Denim dilarang keras dipakai untuk pendakian dan kemah alam bebas karena alasan medis, yaitu...', '["A. Mudah sobek terkena ranting","B. Berat, menahan panas, dan sangat sulit kering jika basah sehingga memicu hipotermia","C. Memantulkan cahaya","D. Mengundang serangga"]'::jsonb, 'B. Berat, menahan panas, dan sangat sulit kering jika basah sehingga memicu hipotermia'),
(99, 'Penerapan prinsip "Pack it in, Pack it out" dalam manajemen sampah perkemahan berarti...', '["A. Membakar semua sampah sebelum pulang","B. Mengubur plastik di dalam tanah","C. Membawa kembali turun semua sampah anorganik untuk dibuang ke tempat yang semestinya","D. Membuang ke sungai terdekat"]'::jsonb, 'C. Membawa kembali turun semua sampah anorganik untuk dibuang ke tempat yang semestinya'),
(99, 'Simpul yang paling praktis untuk menautkan tali tenda pada pasak karena bisa ditarik ulur (dikencangkan/dikendurkan) tanpa melepas simpul adalah...', '["A. Simpul Pangkal","B. Simpul Tali Tenda (Taut-line Hitch)","C. Simpul Mati","D. Simpul Delapan"]'::jsonb, 'B. Simpul Tali Tenda (Taut-line Hitch)'),
(99, 'Jarak minimal yang direkomendasikan untuk membangun MCK (Mandi Cuci Kakus) darurat dari sumber mata air agar tidak mencemari lingkungan adalah...', '["A. 2 meter","B. 5 meter","C. 15 - 20 meter","D. Bebas"]'::jsonb, 'C. 15 - 20 meter'),
(99, 'Menurut standar telegrafi internasional, perbandingan durasi waktu antara ketukan "titik" (dot) dan "garis" (dash) dalam sandi Morse adalah...', '["A. 1 : 2","B. 1 : 3","C. 2 : 3","D. 1 : 4"]'::jsonb, 'B. 1 : 3'),
(99, 'Isyarat prosedural (Prosign) standar internasional untuk "Attention" atau tanda memulai pesan Morse yang sah adalah...', '["A. -.-.-.","B. .-...-","C. -.-.-","D. ...-.-"]'::jsonb, 'C. -.-.-'),
(99, 'Jika huruf "O" adalah (---) dan "S" adalah (...), maka huruf "C" dalam kode morse adalah...', '["A. -.-.","B. --.-","C. -..-","D. .--."]'::jsonb, 'A. -.-.'),
(99, 'Jika memecahkan kata menggunakan "Sandi AND", hal pertama yang harus dilakukan adalah...', '["A. Mengganti semua vokal","B. Menghapus semua rangkaian huruf A-N-D yang berdekatan","C. Membaca dari belakang","D. Mengubahnya ke angka"]'::jsonb, 'B. Menghapus semua rangkaian huruf A-N-D yang berdekatan'),
(99, 'Huruf Q dan P dalam kode morse memiliki kombinasi garis yang mengecoh. Kombinasi yang benar secara berurutan untuk Q dan P adalah...', '["A. --.- dan .--.","B. .--. dan --.-","C. -.-. dan -..-","D. --.- dan -..."]'::jsonb, 'A. --.- dan .--.'),
(99, 'Isyarat bahwa pesan telah selesai seluruhnya (End of Message) dikirimkan dengan sandi...', '["A. SK (...-.-)","B. AR (.-.-.)","C. BT (-...-)","D. AS (.-...)"]'::jsonb, 'B. AR (.-.-.)'),
(99, 'Jika membaca peta topografi berskala 1:50.000 dan jarak dua titik di peta adalah 4 cm, maka jarak sebenarnya di medan adalah...', '["A. 200 meter","B. 2 kilometer","C. 4 kilometer","D. 20 kilometer"]'::jsonb, 'B. 2 kilometer'),
(99, 'Garis kontur yang tergambar menjorok ke arah tempat yang lebih tinggi (membentuk huruf V terbalik) secara topografi merupakan...', '["A. Punggungan bukit","B. Lembah atau aliran air","C. Puncak gunung","D. Dataran rendah"]'::jsonb, 'B. Lembah atau aliran air'),
(99, 'Aturan baku "Golden Rule" dalam membaca koordinat Grid (UTM) 6 angka pada peta topografi adalah...', '["A. Baca garis vertikal dulu (Easting ke kanan), lalu garis horizontal (Northing ke atas)","B. Baca ke atas dulu baru ke kanan","C. Baca dari pusat ke luar","D. Baca garis miring"]'::jsonb, 'A. Baca garis vertikal dulu (Easting ke kanan), lalu garis horizontal (Northing ke atas)'),
(99, 'Perbedaan sudut putar yang ditunjukkan antara Utara Magnetis di jarum kompas dan Utara Peta (Grid) pada selembar peta disebut...', '["A. Deviasi","B. Inclinasi","C. Deklinasi Magnetis","D. Variasi Meridian"]'::jsonb, 'C. Deklinasi Magnetis'),
(99, 'Alat mekanis dengan roda gigi kecil yang dijalankan menyusuri kelokan sungai di peta untuk menghitung jarak rute melengkung disebut...', '["A. Altimeter","B. Protractor","C. Planimeter","D. Curvimeter"]'::jsonb, 'D. Curvimeter'),
(99, 'Metode navigasi siang hari tanpa kompas menggunakan bayangan tongkat tegak lurus yang memanfaatkan pergerakan semu matahari disebut...', '["A. Resection bayangan","B. Sundial (Metode Bayangan Matahari)","C. Kompas alam","D. Proyeksi silinder"]'::jsonb, 'B. Sundial (Metode Bayangan Matahari)'),
(99, 'Dalam pemecahan Sandi Kotak 2, satu kotak kerangka silang dihuni oleh 3 huruf. Jika terdapat 2 titik di atas kerangka tersebut, maka itu menunjukkan huruf...', '["A. Pertama","B. Kedua","C. Ketiga","D. Keempat"]'::jsonb, 'C. Ketiga'),
(99, 'Sandi Kimia mengonversi kode Morse ke huruf. Jika kode aslinya adalah "H2O" (H=konsonan, O=vokal), maka morse yang terbentuk adalah...', '["A. ..-","B. -..","C. --.","D. .--"]'::jsonb, 'C. --.'),
(99, 'Sandi yang menggunakan patokan waktu dengan selisih yang konstan (misal pukul 08.00 = A, 08.05 = B, 08.10 = C) disebut...', '["A. Sandi Geser","B. Sandi Waktu","C. Sandi Jam","D. Sandi Datar"]'::jsonb, 'C. Sandi Jam'),
(99, 'Sandi AZ menukar huruf awal dengan huruf akhir alfabet. Jika sandinya berbunyi "K", maka huruf aslinya adalah...', '["A. O","B. P","C. N","D. M"]'::jsonb, 'B. P'),
(99, 'Sandi yang bentuk fisiknya memanjang menyerupai gerigi atau gelombang naik turun tanpa spasi putus disebut...', '["A. Sandi Rumput","B. Sandi Sungai","C. Sandi Ular / Sandi Gergaji","D. Sandi Ombak"]'::jsonb, 'C. Sandi Ular / Sandi Gergaji'),
(99, 'Dalam Sandi Koordinat tabel 5x5 dengan kata kunci "MERAH PUTIH", huruf A terletak pada titik temu kordinat...', '["A. Baris M, Kolom P","B. Baris M, Kolom U","C. Baris E, Kolom H","D. Baris A, Kolom I"]'::jsonb, 'A. Baris M, Kolom P'),
(99, 'Tindakan Pertolongan Pertama yang BENAR pada korban kecelakaan yang mimisan (hidung berdarah) adalah...', '["A. Menengadahkan kepala jauh ke belakang","B. Memasukkan kapas ke dalam lubang hidung","C. Menundukkan kepala ke depan dan menjepit cuping hidung selama 10 menit","D. Berbaring telentang"]'::jsonb, 'C. Menundukkan kepala ke depan dan menjepit cuping hidung selama 10 menit'),
(99, 'Rasio kompresi dada (pijat jantung) dan bantuan napas buatan pada RJP (Resusitasi Jantung Paru) untuk 1 orang penolong menurut standar medis terbaru adalah...', '["A. 15 kompresi : 2 napas","B. 30 kompresi : 2 napas","C. 5 kompresi : 1 napas","D. 10 kompresi : 2 napas"]'::jsonb, 'B. 30 kompresi : 2 napas'),
(99, 'Penanganan keseleo (terkilir) di lapangan paling efektif menggunakan metode RICE, yang merupakan singkatan dari...', '["A. Rest, Ice, Compression, Elevation","B. Run, Ice, Cool, Elevate","C. Rest, Iron, Cold, Energy","D. Race, Immobilize, Compression, Eat"]'::jsonb, 'A. Rest, Ice, Compression, Elevation'),
(99, 'Alasan dilarangnya mengoleskan pasta gigi, mentega, atau kecap pada luka bakar melepuh adalah...', '["A. Karena dapat mengubah pigmen kulit","B. Karena zat tersebut menahan/memerangkap sisa panas di dalam kulit dan memicu infeksi hebat","C. Karena membuat luka sulit diperban","D. Karena dapat menghentikan pendarahan secara tiba-tiba"]'::jsonb, 'B. Karena zat tersebut menahan/memerangkap sisa panas di dalam kulit dan memicu infeksi hebat'),
(99, 'Jika digigit ular berbisa di tengah hutan, penanganan paling krusial sebelum di bawa ke RS adalah...', '["A. Mengisap bisa dari luka menggunakan mulut","B. Mengikat tourniquet mati di pangkal lengan/kaki","C. Imobilisasi (membidai area gigitan agar korban tidak bergerak sama sekali) untuk menahan laju penyebaran racun di kelenjar getah bening","D. Mengoleskan lumpur"]'::jsonb, 'C. Imobilisasi (membidai area gigitan agar korban tidak bergerak sama sekali) untuk menahan laju penyebaran racun di kelenjar getah bening'),
(99, 'Luka tusuk yang diakibatkan oleh benda kotor berkarat (seperti paku) sangat berisiko fatal jika tidak dicuci bersih karena membawa bakteri penyebab...', '["A. Rabies","B. Polio","C. Tetanus","D. Demam Berdarah"]'::jsonb, 'C. Tetanus'),
(99, 'Pembalut elastis berwarna coklat (Elastic Bandage) sangat direkomendasikan berada di dalam kotak P3K Pramuka karena berfungsi spesifik untuk...', '["A. Membalut luka bakar luas","B. Membebat cedera persendian (terkilir/keseleo) agar tidak bengkak","C. Menghapus darah","D. Membuat tandu"]'::jsonb, 'B. Membebat cedera persendian (terkilir/keseleo) agar tidak bengkak');
